def dbsize(db_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "dbsize",
            "timestamp": _iso(now),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(db_id, str) or not re.match(r"^rdb_[0-9A-HJKMNP-TV-Z]{10,}$", db_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "db_id is missing or invalid format", field="db_id")

    dbs = _load("redis_databases.json")
    if not isinstance(dbs, list):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Database not found")
    db = next((r for r in dbs if isinstance(r, dict) and r.get("id") == db_id), None)
    if not db:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Database not found", db_id=db_id)
    if db.get("status") == "disabled":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Database not accessible", db_id=db_id)

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []

    cnt = 0
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("db_id") != db_id:
            continue
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        cnt += 1

    _log("ok")
    return {"db_id": db_id, "count": cnt}

def info(section=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "info",
            "timestamp": _iso(now),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    if section is None:
        section = "default"
    if not isinstance(section, str) or not section:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "section must be a non-empty string", field="section")

    # Choose the "configured default db": prefer a single active DB if exists; else any non-disabled DB.
    dbs = _load("redis_databases.json")
    if not isinstance(dbs, list):
        dbs = []
    active = [d for d in dbs if isinstance(d, dict) and d.get("status") in ("active", "read_only")]
    default_db = None
    if len(active) == 1:
        default_db = active[0]
    elif len(active) > 1:
        # If multiple, pick the one with smallest db_number to behave deterministically.
        def _dbn(x):
            v = x.get("db_number")
            return v if isinstance(v, int) else 10**9
        active_sorted = sorted(active, key=_dbn)
        default_db = active_sorted[0]
    else:
        # no active/read_only; pick any non-disabled for info display
        non_disabled = [d for d in dbs if isinstance(d, dict) and d.get("status") != "disabled"]
        if non_disabled:
            default_db = non_disabled[0]

    # Compute basic stats from store
    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []
    sessions = _load("redis_runtime_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    db_id = default_db.get("id") if isinstance(default_db, dict) else None

    total_keys = 0
    active_keys = 0
    expired_keys = 0
    deleted_keys = 0
    now_dt = now
    if db_id:
        for k in keys:
            if not isinstance(k, dict) or k.get("db_id") != db_id:
                continue
            total_keys += 1
            st = k.get("status")
            if st == "deleted":
                deleted_keys += 1
                continue
            exp = _parse_dt(k.get("expires_at"))
            if st == "active" and exp is not None and exp <= now_dt:
                expired_keys += 1
                continue
            if st == "expired":
                expired_keys += 1
                continue
            if st == "active":
                active_keys += 1

    # Approx memory: sum approx_size_bytes for active, non-expired keys; fallback to rough size by JSON length.
    approx_mem = 0
    if db_id:
        for k in keys:
            if not isinstance(k, dict) or k.get("db_id") != db_id:
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            sz = k.get("approx_size_bytes")
            if isinstance(sz, int) and sz >= 0:
                approx_mem += sz
        if approx_mem == 0:
            # rough fallback: values JSON size
            for v in values:
                if not isinstance(v, dict) or v.get("db_id") != db_id:
                    continue
                approx_mem += len(json.dumps(v, ensure_ascii=False))

    connected_clients = 0
    if db_id:
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("db_id") != db_id:
                continue
            if s.get("session_type") == "client_connection" and s.get("status") == "active":
                connected_clients += 1

    # Sectioned output (lightweight; consistent dictionary response)
    base = {
        "server": {
            "service": "Redis",
            "timestamp": _iso(now),
            "redis_version": default_db.get("redis_version") if isinstance(default_db, dict) else None,
            "modules": default_db.get("modules") if isinstance(default_db, dict) else None,
        },
        "database": {
            "default_db_id": db_id,
            "status": default_db.get("status") if isinstance(default_db, dict) else None,
            "db_number": default_db.get("db_number") if isinstance(default_db, dict) else None,
            "name": default_db.get("name") if isinstance(default_db, dict) else None,
        },
        "stats": {
            "keys_total": total_keys,
            "keys_active": active_keys,
            "keys_expired": expired_keys,
            "keys_deleted": deleted_keys,
            "connected_clients": connected_clients,
        },
        "memory": {
            "approx_used_memory_bytes": approx_mem,
        },
    }

    if section == "default":
        out = base
    elif section == "memory":
        out = {"memory": base["memory"], "database": base["database"]}
    elif section == "stats":
        out = {"stats": base["stats"], "database": base["database"]}
    elif section == "server":
        out = {"server": base["server"], "database": base["database"]}
    else:
        # unknown sections return empty but valid envelope
        out = {"section": section, "data": {}}

    _log("ok")
    return out

def client_list(db_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow()

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "client_list",
            "timestamp": _iso(now),
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(db_id, str) or not re.match(r"^rdb_[0-9A-HJKMNP-TV-Z]{10,}$", db_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "db_id is missing or invalid format", field="db_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "closed"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, closed", field="status")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        # cursor is opaque; implement as base64("v1:<offset>")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("v1:"):
                raise ValueError("bad prefix")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("negative")
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    dbs = _load("redis_databases.json")
    if not isinstance(dbs, list):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Database not found")
    db = next((r for r in dbs if isinstance(r, dict) and r.get("id") == db_id), None)
    if not db or db.get("status") == "disabled":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Database not found or not accessible", db_id=db_id)

    sessions = _load("redis_runtime_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    rows = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("db_id") != db_id:
            continue
        if s.get("session_type") != "client_connection":
            continue
        if status is not None and s.get("status") != status:
            continue
        rows.append(s)

    # Deterministic order: created_at then id
    def _key(r):
        ca = r.get("created_at")
        return (ca if isinstance(ca, str) else "", r.get("id") if isinstance(r.get("id"), str) else "")
    rows.sort(key=_key)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        nxt = start + limit
        token = f"v1:{nxt}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "db_id": db_id,
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

def delete(key, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits(kind):
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            limits = {}
        if not limits or limits.get("enforce") is False:
            return None

        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = _now_dt()

        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)

        qpd = limits.get("requests_per_day")
        if isinstance(qpd, int) and qpd > 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= day_start:
                    cnt += 1
            if cnt >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", limit=qpd, window="day")

        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        db_rows = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not db_rows:
            return None, _err("NOT_FOUND", "No Redis databases exist")

        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        # If a configured default exists, use it.
        if isinstance(default_db_id, str) and default_db_id:
            db = next((d for d in db_rows if d.get("id") == default_db_id), None)
            if not db:
                return None, _err("NOT_FOUND", "Configured default database not found", default_db_id=default_db_id)
            if db.get("status") == "disabled":
                return None, _err("INVALID_TRANSITION", "Default database is disabled", db_id=db.get("id"))
            return db, None

        # Otherwise, choose a usable default: prefer active/read_only; lowest db_number.
        usable = [d for d in db_rows if d.get("status") in ("active", "read_only")]
        if not usable:
            return None, _err("UNAUTHORIZED", "No usable default database available")

        usable_with_num = [d for d in usable if isinstance(d.get("db_number"), int)]
        if usable_with_num:
            db = sorted(usable_with_num, key=lambda x: x["db_number"])[0]
        else:
            db = usable[0]

        if db.get("status") == "disabled":
            return None, _err("INVALID_TRANSITION", "Default database is disabled", db_id=db.get("id"))
        return db, None

    # Validate
    if not isinstance(key, str) or not key.strip():
        _log("error", "VALIDATION_ERROR", {"field": "key"})
        return _err("VALIDATION_ERROR", "key must be a non-empty string", field="key")

    limerr = _enforce_limits("write")
    if limerr:
        _log("error", limerr["error"]["code"])
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"])
        return dberr
    db_id = db["id"]

    # Locate active, non-expired key
    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    now = _now_dt()

    target = None
    for r in keys:
        if not isinstance(r, dict):
            continue
        if r.get("db_id") != db_id:
            continue
        if r.get("key_name") != key:
            continue
        if r.get("status") != "active":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        target = r
        break

    if not target:
        _log("error", "NOT_FOUND", {"db_id": db_id, "key": key})
        return _err("NOT_FOUND", "Key not found or not active", key=key)

    # Mutate: set status=deleted; update updated_at
    # Enforce lifecycle transition active -> deleted
    target["status"] = "deleted"
    target["updated_at"] = _now_iso()

    # Remove value row (or rely on cascade; we implement explicit delete)
    vals = _load("redis_values.json")
    if not isinstance(vals, list):
        vals = []
    key_id = target.get("id")
    if isinstance(key_id, str) and key_id:
        new_vals = [v for v in vals if not (isinstance(v, dict) and v.get("key_id") == key_id)]
        if len(new_vals) != len(vals):
            vals = new_vals

    _save("redis_keys.json", keys)
    _save("redis_values.json", vals)

    _log("ok", None, {"db_id": db_id, "key_id": key_id, "key": key})
    return {
        "key": key,
        "deleted": True,
        "db_id": db_id,
        "key_id": key_id,
    }

def type(key, **_extra):
    import json, os, datetime, time, fnmatch, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    logs_name = "redis_request_logs.json"
    logs = _load(logs_name)

    def _log(status, error_code=None, error_message=None):
        dt_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": "type",
            "timestamp": now_iso,
            "latency_ms": dt_ms,
            "status": status
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = error_message
        logs.append(row)
        _save(logs_name, logs)

    # Rate limit: 120 reads/minute across all calls (observable via logs)
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dts = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dts >= cutoff:
                recent += 1
    if recent >= 120:
        _log("error", "RATE_LIMIT", "Too many requests")
        return _err("RATE_LIMIT", "Too many requests")

    if not isinstance(key, str) or not key.strip():
        _log("error", "VALIDATION_ERROR", "key must be a non-empty string")
        return _err("VALIDATION_ERROR", "key must be a non-empty string")

    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if d.get("status") == "active":
            default_db = d
            break
    if not default_db:
        # If there are DBs but none active, unauthorized to operate
        _log("error", "UNAUTHORIZED", "No active database available")
        return _err("UNAUTHORIZED", "No active database available")

    if default_db.get("status") == "disabled":
        _log("error", "UNAUTHORIZED", "Default database is disabled")
        return _err("UNAUTHORIZED", "Default database is disabled")

    keys = _load("redis_keys.json")
    db_id = default_db.get("id")

    def _is_expired(krow):
        if krow.get("status") != "active":
            return True
        exp = krow.get("expires_at")
        if exp is None:
            return False
        if not isinstance(exp, str):
            return False
        try:
            exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return False
        return exp_dt <= now

    krow = None
    for r in keys:
        if r.get("db_id") == db_id and r.get("key_name") == key:
            krow = r
            break

    if not krow or _is_expired(krow):
        # Redis returns "none" when not found
        _log("ok")
        return {"type": "none", "key": key}

    kt = krow.get("key_type")
    _log("ok")
    return {"type": kt if isinstance(kt, str) else "none", "key": key}

def expire(name, expire_seconds, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "expire"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rlog_{int(_now_dt().timestamp()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits(is_write=False):
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None

        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = _now_dt()
        rpm = limits.get("write_requests_per_minute") if is_write else None
        if not isinstance(rpm, int) or rpm <= 0:
            rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)

        qpd = limits.get("write_requests_per_day") if is_write else None
        if not isinstance(qpd, int) or qpd <= 0:
            qpd = limits.get("requests_per_day")
        if isinstance(qpd, int) and qpd > 0:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= day_start:
                    cnt += 1
            if cnt >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", limit=qpd, window="day")
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        # If configured id exists, use it.
        if isinstance(default_db_id, str) and default_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == default_db_id:
                    if d.get("status") == "disabled":
                        return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=default_db_id)
                    return d, None

        # Otherwise choose any usable (active/read_only) db
        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        # If only disabled exist, treat as unavailable
        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    # Validate inputs
    if not isinstance(name, str) or not name:
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(expire_seconds, int):
        _log("error", "VALIDATION_ERROR", {"field": "expire_seconds"})
        return _err("VALIDATION_ERROR", "expire_seconds must be an integer", field="expire_seconds")
    if expire_seconds < 1:
        _log("error", "VALIDATION_ERROR", {"field": "expire_seconds"})
        return _err("VALIDATION_ERROR", "expire_seconds must be >= 1", field="expire_seconds")

    limerr = _enforce_limits(is_write=True)
    if limerr:
        _log("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []

    now = _now_dt()

    # Find active, non-expired key by name in default db
    target = None
    for r in keys:
        if not isinstance(r, dict):
            continue
        if r.get("db_id") != db_id or r.get("key_name") != name:
            continue
        if r.get("status") != "active":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        target = r
        break

    if target is None:
        _log("error", "NOT_FOUND", {"key": name}, db_id=db_id)
        return _err("NOT_FOUND", "Key not found or not active", key=name)

    target["ttl_seconds"] = expire_seconds
    target["expires_at"] = (now + datetime.timedelta(seconds=expire_seconds)).isoformat() + "Z"
    target["updated_at"] = _now_iso()

    _save("redis_keys.json", keys)
    _log("ok", None, {"key": name, "expire_seconds": expire_seconds}, db_id=db_id)
    return {"status": "success", "key": name, "expire_seconds": expire_seconds, "expires_at": target["expires_at"]}

