    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits(is_write=False):
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None

        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = _now_dt()
        rpm = limits.get("write_requests_per_minute") if is_write else None
        if not isinstance(rpm, int) or rpm <= 0:
            rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        if isinstance(default_db_id, str) and default_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == default_db_id:
                    if d.get("status") == "disabled":
                        return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=default_db_id)
                    return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    if not isinstance(old_key, str) or not old_key:
        _log("error", "VALIDATION_ERROR", {"field": "old_key"})
        return _err("VALIDATION_ERROR", "old_key must be a non-empty string", field="old_key")
    if not isinstance(new_key, str) or not new_key:
        _log("error", "VALIDATION_ERROR", {"field": "new_key"})
        return _err("VALIDATION_ERROR", "new_key must be a non-empty string", field="new_key")

    limerr = _enforce_limits(is_write=True)
    if limerr:
        _log("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []

    now = _now_dt()

    def _is_active_not_expired(r):
        if not isinstance(r, dict):
            return False
        if r.get("status") != "active":
            return False
        exp = _parse_dt(r.get("expires_at"))
        return exp is None or exp > now

    src = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == old_key and _is_active_not_expired(r):
            src = r
            break

    if src is None:
        _log("error", "NOT_FOUND", {"key": old_key}, db_id=db_id)
        return _err("NOT_FOUND", f"Key '{old_key}' not found or not active", key=old_key)

    # Idempotent: renaming to same name is a no-op success
    if old_key == new_key:
        _log("ok", None, {"old_key": old_key, "new_key": new_key, "idempotent": True}, db_id=db_id)
        return {"status": "success", "message": "Key name unchanged", "old_key": old_key, "new_key": new_key}

    # Check conflict for active key with new_key
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == new_key and _is_active_not_expired(r):
            _log("error", "CONFLICT", {"new_key": new_key}, db_id=db_id)
            return _err("CONFLICT", f"Key '{new_key}' already exists", key=new_key)

    src["key_name"] = new_key
    src["updated_at"] = _now_iso()
    _save("redis_keys.json", keys)

    _log("ok", None, {"old_key": old_key, "new_key": new_key}, db_id=db_id)
    return {"status": "success", "message": f"Renamed '{old_key}' to '{new_key}'", "old_key": old_key, "new_key": new_key}

def scan_keys(pattern=None, count=None, cursor=None, **_extra):
    import json, os, datetime, time, fnmatch, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    logs_name = "redis_request_logs.json"
    logs = _load(logs_name)

    def _log(status, error_code=None, error_message=None):
        dt_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": "scan_keys",
            "timestamp": now_iso,
            "latency_ms": dt_ms,
            "status": status
        }
        if error_code:
            row["error_code"] = error_code
        if error_message:
            row["error_message"] = error_message
        logs.append(row)
        _save(logs_name, logs)

    # Rate limit: 120 reads/minute across all reads
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dts = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dts >= cutoff:
                recent += 1
    if recent >= 120:
        _log("error", "RATE_LIMIT", "Too many requests")
        return _err("RATE_LIMIT", "Too many requests")

    if pattern is None:
        pattern = "*"
    if count is None:
        count = 100
    if cursor is None:
        cursor = 0

    if not isinstance(pattern, str) or pattern == "":
        _log("error", "VALIDATION_ERROR", "pattern must be a non-empty string")
        return _err("VALIDATION_ERROR", "pattern must be a non-empty string")
    if not isinstance(count, int):
        _log("error", "VALIDATION_ERROR", "count must be an integer")
        return _err("VALIDATION_ERROR", "count must be an integer")
    if count < 1 or count > 10000:
        _log("error", "VALIDATION_ERROR", "count must be between 1 and 10000")
        return _err("VALIDATION_ERROR", "count must be between 1 and 10000")
    if not isinstance(cursor, int) or cursor < 0:
        _log("error", "VALIDATION_ERROR", "cursor must be a non-negative integer")
        return _err("VALIDATION_ERROR", "cursor must be a non-negative integer")

    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if d.get("status") == "active":
            default_db = d
            break
    if not default_db:
        _log("error", "UNAUTHORIZED", "No active database available")
        return _err("UNAUTHORIZED", "No active database available")
    if default_db.get("status") == "disabled":
        _log("error", "UNAUTHORIZED", "Default database is disabled")
        return _err("UNAUTHORIZED", "Default database is disabled")

    keys = _load("redis_keys.json")
    db_id = default_db.get("id")

    def _expired(krow):
        exp = krow.get("expires_at")
        if exp is None:
            return False
        if not isinstance(exp, str):
            return False
        try:
            exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return False
        return exp_dt <= now

    # Construct stable ordered list of eligible keys (active, not expired) then paginate by cursor index.
    eligible = []
    for r in keys:
        if r.get("db_id") != db_id:
            continue
        if r.get("status") != "active":
            continue
        if _expired(r):
            continue
        kn = r.get("key_name")
        if isinstance(kn, str) and fnmatch.fnmatch(kn, pattern):
            eligible.append(kn)

    eligible.sort()
    n = len(eligible)
    if cursor >= n:
        # Cursor beyond end: return empty and cursor=0
        _log("ok")
        return {"cursor": 0, "keys": [], "count": count, "pattern": pattern, "total_matched": n}

    batch = eligible[cursor:cursor + count]
    next_cursor = cursor + count
    if next_cursor >= n:
        next_cursor = 0

    _log("ok")
    return {
        "cursor": next_cursor,
        "keys": batch,
        "count": count,
        "pattern": pattern,
        "total_matched": n,
        "returned": len(batch)
    }

def scan_all_keys(pattern="*", batch_size=100, **_extra):
    import json, os, datetime, fnmatch, time, base64, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # ---- helpers for request logging / quotas ----
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log():
        name = "redis_request_logs.json"
        path = os.path.join(_DB, name)
        if not os.path.exists(path):
            _save(name, [])
        return name

    def _log(endpoint, status_code, error_code=None, meta=None, credential_id=None):
        name = _ensure_request_log()
        logs = _load(name)
        row = {
            "id": "rlog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        }
        logs.append(row)
        _save(name, logs)

    def _enforce_rate_limit(endpoint, limit_per_min=120):
        name = _ensure_request_log()
        logs = _load(name)
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                c += 1
        if c >= limit_per_min:
            return False
        return True

    endpoint = "scan_all_keys"

    if not _enforce_rate_limit(endpoint, limit_per_min=300):
        _log(endpoint, 429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded for scan_all_keys")

    # ---- validate inputs ----
    if pattern is None:
        pattern = "*"
    if not isinstance(pattern, str):
        _log(endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pattern must be a string")
    if not isinstance(batch_size, int):
        _log(endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "batch_size must be an integer")
    if batch_size < 1 or batch_size > 10000:
        _log(endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "batch_size must be between 1 and 10000")

    # ---- resolve default DB context ----
    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if d.get("status") == "active":
            default_db = d
            break
    if default_db is None:
        for d in dbs:
            if d.get("status") == "read_only":
                default_db = d
                break
    if default_db is None:
        _log(endpoint, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No usable redis database context is configured")
    if default_db.get("status") == "disabled":
        _log(endpoint, 409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Default redis database is disabled", db_id=default_db.get("id"))

    default_db_id = default_db.get("id")
    now = datetime.datetime.utcnow()

    keys = _load("redis_keys.json")

    # Implement scan_all_keys by iterating a deterministic scan cursor over eligible keys
    eligible = []
    for k in keys:
        if k.get("db_id") != default_db_id:
            continue
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        name = k.get("key_name")
        if not isinstance(name, str):
            continue
        if fnmatch.fnmatch(name, pattern):
            eligible.append(name)

    eligible.sort()
    # Iterate in batches, producing same observable cursor behavior as repeated scan_keys
    cursor = 0
    all_results = []
    iterations = 0
    total = len(eligible)
    while True:
        if cursor >= total:
            cursor = 0
            break
        nxt = min(cursor + batch_size, total)
        all_results.extend(eligible[cursor:nxt])
        iterations += 1
        cursor = 0 if nxt >= total else nxt
        if cursor == 0:
            break

    resp = {
        "data": {
            "pattern": pattern,
            "batch_size": batch_size,
            "keys": all_results,
            "count": len(all_results),
            "iterations": iterations
        }
    }
    _log(endpoint, 200, None, meta={"db_id": default_db_id, "returned": len(all_results), "iterations": iterations})
    return resp

def get_indexes(db_id, status=None, index_type=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_indexes"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log():
        name = "redis_request_logs.json"
        path = os.path.join(_DB, name)
        if not os.path.exists(path):
            _save(name, [])
        return name

    def _log(status_code, error_code=None, meta=None, credential_id=None):
        name = _ensure_request_log()
        logs = _load(name)
        logs.append({
            "id": "rlog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save(name, logs)

    def _rate_ok(limit_per_min=240):
        logs = _load(_ensure_request_log())
        now = datetime.datetime.utcnow()
        ws = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= ws:
                c += 1
        return c < limit_per_min

    if not _rate_ok(400):
        _log(429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded for get_indexes")

    # ---- validate ----
    if not isinstance(db_id, str) or not db_id.startswith("rdb_"):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "db_id is required and must be a string matching the expected format")
    if status is not None:
        if not isinstance(status, str) or status not in ("creating", "ready", "failed", "deleted"):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of creating, ready, failed, deleted")
    if index_type is not None:
        if not isinstance(index_type, str) or index_type not in ("vector_hnsw_hash",):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "index_type must be vector_hnsw_hash")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided")

    # ---- db existence and disabled default rule (reject if this db is disabled) ----
    dbs = _load("redis_databases.json")
    db_row = None
    for d in dbs:
        if d.get("id") == db_id:
            db_row = d
            break
    if db_row is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Redis database not found", db_id=db_id)
    if db_row.get("status") == "disabled":
        _log(409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Redis database is disabled", db_id=db_id)

    # ---- pagination cursor ----
    start = 0
    if cursor:
        try:
            start = int(cursor)
            if start < 0:
                raise ValueError()
        except Exception:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    idxs = _load("redis_search_indexes.json")
    rows = []
    for r in idxs:
        if r.get("db_id") != db_id:
            continue
        if r.get("status") == "deleted":
            continue
        if status is not None and r.get("status") != status:
            continue
        if index_type is not None and r.get("index_type") != index_type:
            continue
        rows.append(r)

    rows.sort(key=lambda x: (x.get("index_name") or "", x.get("id") or ""))

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = str(start + limit)

    # Return list of index names (as per business rule), with metadata envelope
    resp = {
        "data": {
            "indexes": [r.get("index_name") for r in page if isinstance(r.get("index_name"), str)],
            "items": page,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log(200, None, meta={"db_id": db_id, "returned": len(page), "total": total})
    return resp

def get_index_info(index_name, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
