        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_index_info"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log():
        name = "redis_request_logs.json"
        path = os.path.join(_DB, name)
        if not os.path.exists(path):
            _save(name, [])
        return name

    def _log(status_code, error_code=None, meta=None, credential_id=None):
        name = _ensure_request_log()
        logs = _load(name)
        logs.append({
            "id": "rlog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save(name, logs)

    def _rate_ok(limit_per_min=240):
        logs = _load(_ensure_request_log())
        now = datetime.datetime.utcnow()
        ws = now - datetime.timedelta(minutes=1)
        c = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= ws:
                c += 1
        return c < limit_per_min

    if not _rate_ok(400):
        _log(429, "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded for get_index_info")

    if not isinstance(index_name, str) or not index_name.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "index_name is required")

    # Resolve default DB context and ensure not disabled
    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if d.get("status") == "active":
            default_db = d
            break
    if default_db is None:
        for d in dbs:
            if d.get("status") == "read_only":
                default_db = d
                break
    if default_db is None:
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No usable redis database context is configured")
    if default_db.get("status") == "disabled":
        _log(409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Default redis database is disabled", db_id=default_db.get("id"))

    db_id = default_db.get("id")

    idxs = _load("redis_search_indexes.json")
    idx = None
    for r in idxs:
        if r.get("db_id") == db_id and r.get("index_name") == index_name:
            idx = r
            break
    if idx is None or idx.get("status") == "deleted":
        _log(404, "NOT_FOUND", meta={"db_id": db_id, "index_name": index_name})
        return _err("NOT_FOUND", "Index not found", index_name=index_name)

    # computed stats: indexed keys count derived by counting eligible hash keys matching prefix
    keys = _load("redis_keys.json")
    values = _load("redis_values.json")
    now = datetime.datetime.utcnow()
    prefix = idx.get("prefix") or ""
    vector_field = idx.get("vector_field")
    value_by_keyid = {}
    for v in values:
        kid = v.get("key_id")
        if isinstance(kid, str):
            value_by_keyid[kid] = v

    indexed = 0
    for k in keys:
        if k.get("db_id") != db_id:
            continue
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        if k.get("key_type") != "hash":
            continue
        kn = k.get("key_name") or ""
        if not isinstance(kn, str) or not kn.startswith(prefix):
            continue
        v = value_by_keyid.get(k.get("id"))
        hv = v.get("hash_value") if isinstance(v, dict) else None
        if not isinstance(hv, dict):
            continue
        if vector_field is not None and isinstance(vector_field, str) and vector_field in hv:
            indexed += 1

    resp = {
        "data": {
            "index": idx,
            "stats": {
                "db_id": db_id,
                "index_name": index_name,
                "indexed_keys": indexed
            }
        }
    }
    _log(200, None, meta={"db_id": db_id, "index_name": index_name, "indexed_keys": indexed})
    return resp

def get_indexed_keys_number(index_name, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_indexed_keys_number"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None

        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = _now_dt()
        rpm = limits.get("index_meta_requests_per_minute", limits.get("requests_per_minute"))
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                # count only this endpoint if per-endpoint limit specified
                if "index_meta_requests_per_minute" in limits and r.get("endpoint") != endpoint:
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        dbs = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not dbs:
            return None, _err("NOT_FOUND", "No Redis databases exist")

        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        candidates = []
        if isinstance(default_db_id, str) and default_db_id:
            candidates = [d for d in dbs if d.get("id") == default_db_id]
        else:
            flagged = [d for d in dbs if d.get("status") in ("active", "read_only") and (d.get("is_default") is True or d.get("default") is True)]
            if flagged:
                candidates = flagged
            else:
                ar = [d for d in dbs if d.get("status") in ("active", "read_only")]
                if ar:
                    with_num = [d for d in ar if isinstance(d.get("db_number"), int)]
                    candidates = sorted(with_num, key=lambda x: x["db_number"]) if with_num else ar

        if not candidates:
            return None, _err("UNAUTHORIZED", "No configured default database available for this operation")

        db = candidates[0]
        if db.get("status") == "disabled":
            return None, _err("UNAUTHORIZED", "Default Redis database is disabled", db_id=db.get("id"))
        return db, None

    if not isinstance(index_name, str) or not index_name.strip():
        _log("error", "VALIDATION_ERROR", {"field": "index_name"})
        return _err("VALIDATION_ERROR", "index_name must be a non-empty string", field="index_name")

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", limit_err["error"]["code"])
        return limit_err

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"])
        return dberr
    db_id = db.get("id")

    indexes = _load("redis_search_indexes.json")
    if not isinstance(indexes, list):
        indexes = []
    idx = None
    for r in indexes:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("index_name") == index_name:
            idx = r
            break

    # Business rule: must return 0 if index deleted or not found (even though docstring says NOT_FOUND).
    if not idx or idx.get("status") == "deleted":
        _log("success", None, {"index_name": index_name, "indexed_keys": 0, "index_found": bool(idx)}, db_id=db_id)
        return {"index_name": index_name, "indexed_keys": 0, "db_id": db_id, "index_status": (idx.get("status") if idx else None)}

    prefix = idx.get("prefix")
    if not isinstance(prefix, str):
        prefix = ""
    now = _now_dt()

    def _is_active_and_not_expired_key(krow):
        if krow.get("status") != "active":
            return False
        exp_dt = _parse_dt(krow.get("expires_at"))
        if exp_dt and exp_dt <= now:
            return False
        return True

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    eligible = 0
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("db_id") != db_id:
            continue
        if not _is_active_and_not_expired_key(k):
            continue
        if k.get("key_type") != "hash":
            continue
        kn = k.get("key_name")
        if isinstance(kn, str) and kn.startswith(prefix):
            eligible += 1

    _log("success", None, {"index_name": index_name, "indexed_keys": eligible}, db_id=db_id)
    return {"index_name": index_name, "indexed_keys": eligible, "db_id": db_id, "index_status": idx.get("status")}

def create_vector_index_hash(index_name=None, prefix=None, vector_field=None, dim=None, distance_metric=None, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "create_vector_index_hash"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None

        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = _now_dt()
        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        dbs = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not dbs:
            return None, _err("NOT_FOUND", "No Redis databases exist")

        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        candidates = []
        if isinstance(default_db_id, str) and default_db_id:
            candidates = [d for d in dbs if d.get("id") == default_db_id]
        else:
            candidates = [d for d in dbs if d.get("status") in ("active", "read_only")]
            if not candidates:
                candidates = [d for d in dbs if d.get("status") != "disabled"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No usable Redis database available")
        db = candidates[0]
        if db.get("status") == "disabled":
            return None, _err("INVALID_TRANSITION", "Default database is disabled", db_id=db.get("id"))
        return db, None

    # Defaults
    if index_name is None:
        index_name = "vector_index"
    if prefix is None:
        prefix = "doc:"
    if vector_field is None:
        vector_field = "vector"
    if dim is None:
        dim = 1536
    if distance_metric is None:
        distance_metric = "COSINE"

    # Validate
    if not isinstance(index_name, str) or not index_name.strip():
        _log("error", "VALIDATION_ERROR", {"field": "index_name"})
        return _err("VALIDATION_ERROR", "index_name must be a non-empty string", field="index_name")
    if not isinstance(prefix, str) or prefix == "":
        _log("error", "VALIDATION_ERROR", {"field": "prefix"})
        return _err("VALIDATION_ERROR", "prefix must be a non-empty string", field="prefix")
    if not isinstance(vector_field, str) or vector_field == "":
        _log("error", "VALIDATION_ERROR", {"field": "vector_field"})
        return _err("VALIDATION_ERROR", "vector_field must be a non-empty string", field="vector_field")
    if not isinstance(dim, int):
        _log("error", "VALIDATION_ERROR", {"field": "dim"})
        return _err("VALIDATION_ERROR", "dim must be an integer", field="dim")
    if dim < 1 or dim > 32768:
        _log("error", "VALIDATION_ERROR", {"field": "dim"})
        return _err("VALIDATION_ERROR", "dim must be between 1 and 32768", field="dim")
    if distance_metric not in ("COSINE", "L2", "IP"):
        _log("error", "VALIDATION_ERROR", {"field": "distance_metric"})
        return _err("VALIDATION_ERROR", "distance_metric must be one of COSINE, L2, IP", field="distance_metric")

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"])
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], dberr["error"])
        return dberr
    db_id = db.get("id")

    indexes = _load("redis_search_indexes.json")
    if not isinstance(indexes, list):
        indexes = []

    # find existing for (db_id,index_name)
    existing = None
    for r in indexes:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("index_name") == index_name:
            existing = r
            break

    now_iso = _now_iso()

    # Idempotent replace-only-if-same-definition
    def _same_def(r):
        return (
            r.get("index_type") == "vector_hnsw_hash" and
            r.get("prefix") == prefix and
            r.get("vector_field") == vector_field and
            r.get("dim") == dim and
            r.get("distance_metric") == distance_metric
        )

    if existing and existing.get("status") != "deleted":
        if _same_def(existing):
            # ensure it's ready (simulate build) if previously creating
            if existing.get("status") == "creating":
                existing["status"] = "ready"
                existing["last_built_at"] = now_iso
                existing["updated_at"] = now_iso
                _save("redis_search_indexes.json", indexes)
            _log("ok", None, {"index_name": index_name, "idempotent": True}, db_id=db_id)
            return {"index_name": index_name, "status": existing.get("status"), "db_id": db_id}
        _log("error", "CONFLICT", {"index_name": index_name, "reason": "definition_mismatch"}, db_id=db_id)
        return _err("CONFLICT", "Index already exists with a different definition", index_name=index_name)

    # Create new row (or resurrect deleted)
    if existing and existing.get("status") == "deleted":
        row = existing
        row["index_type"] = "vector_hnsw_hash"
        row["prefix"] = prefix
        row["vector_field"] = vector_field
        row["dim"] = dim
        row["distance_metric"] = distance_metric
        row["status"] = "creating"
        row["updated_at"] = now_iso
        # keep created_at as is
    else:
        row = {
            "id": "ridx_" + uuid.uuid4().hex,
            "db_id": db_id,
            "index_name": index_name,
            "index_type": "vector_hnsw_hash",
            "prefix": prefix,
            "vector_field": vector_field,
            "dim": dim,
            "distance_metric": distance_metric,
            "status": "creating",
            "last_built_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        indexes.append(row)

    # Simulate build: creating -> ready (or failed if something impossible; here always ready)
    row["status"] = "ready"
    row["last_built_at"] = now_iso
    row["updated_at"] = now_iso

    _save("redis_search_indexes.json", indexes)
    _log("ok", None, {"index_name": index_name, "status": row.get("status")}, db_id=db_id)
    return {"id": row.get("id"), "db_id": db_id, "index_name": index_name, "status": row.get("status")}

def vector_search_hash(query_vector, index_name=None, vector_field=None, k=None, return_fields=None, **_extra):
    import json, os, datetime, time, uuid, base64, struct, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "vector_search_hash"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _audit(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rlog_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None

        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = _now_dt()
        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        if isinstance(default_db_id, str) and default_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == default_db_id:
                    if d.get("status") == "disabled":
                        return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=default_db_id)
                    return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    def _coerce_query_vector(qv):
        # Accept:
        # - list/tuple of numbers
        # - list with single base64 string containing float32 blob
        if isinstance(qv, (list, tuple)):
            if len(qv) == 1 and isinstance(qv[0], str):
                s = qv[0].strip()
                try:
                    raw = base64.b64decode(s, validate=False)
                    if len(raw) % 4 != 0 or len(raw) == 0:
                        return None, _err("VALIDATION_ERROR", "query_vector base64 must decode to a non-empty float32 blob", kind="base64_float32")
                    n = len(raw) // 4
                    vals = list(struct.unpack("<" + "f" * n, raw))
                    return vals, None
                except Exception:
                    return None, _err("VALIDATION_ERROR", "query_vector base64 is not decodable", kind="base64_float32")
            vals = []
            for i, x in enumerate(qv):
                if isinstance(x, bool) or x is None:
                    return None, _err("VALIDATION_ERROR", "query_vector must contain only numbers", index=i)
                if isinstance(x, (int, float)):
                    if not math.isfinite(float(x)):
                        return None, _err("VALIDATION_ERROR", "query_vector must contain only finite numbers", index=i)
                    vals.append(float(x))
                else:
                    # allow numeric strings
                    if isinstance(x, str):
                        try:
                            fx = float(x)
                        except Exception:
                            return None, _err("VALIDATION_ERROR", "query_vector must contain only numbers", index=i)
                        if not math.isfinite(fx):
                            return None, _err("VALIDATION_ERROR", "query_vector must contain only finite numbers", index=i)
                        vals.append(fx)
                    else:
                        return None, _err("VALIDATION_ERROR", "query_vector must contain only numbers", index=i)
            if not vals:
                return None, _err("VALIDATION_ERROR", "query_vector must not be empty")
            return vals, None
        return None, _err("VALIDATION_ERROR", "query_vector must be an array")

    # Validate parameters
    if index_name is None:
        index_name = "vector_index"
    if vector_field is None:
        vector_field = "vector"
    if k is None:
        k = 5

    if not isinstance(index_name, str) or not index_name:
        _audit("error", "VALIDATION_ERROR", {"field": "index_name"})
        return _err("VALIDATION_ERROR", "index_name must be a non-empty string", field="index_name")
    if not isinstance(vector_field, str) or not vector_field:
        _audit("error", "VALIDATION_ERROR", {"field": "vector_field"})
        return _err("VALIDATION_ERROR", "vector_field must be a non-empty string", field="vector_field")
    if not isinstance(k, int) or k < 1 or k > 10000:
        _audit("error", "VALIDATION_ERROR", {"field": "k"})
        return _err("VALIDATION_ERROR", "k must be an integer in 1..10000", field="k")
    if return_fields is not None:
        if not isinstance(return_fields, list) or any((not isinstance(f, str) or not f) for f in return_fields):
            _audit("error", "VALIDATION_ERROR", {"field": "return_fields"})
            return _err("VALIDATION_ERROR", "return_fields must be an array of non-empty strings or null", field="return_fields")

    limerr = _enforce_limits()
    if limerr:
        _audit("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _audit("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    qv, qverr = _coerce_query_vector(query_vector)
    if qverr:
        _audit("error", qverr["error"]["code"], {"op": "coerce_query_vector"}, db_id=db_id)
        return qverr

    indexes = _load("redis_search_indexes.json")
    if not isinstance(indexes, list):
        indexes = []
    idx = None
    for r in indexes:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("index_name") == index_name:
            if r.get("status") == "ready":
                idx = r
                break
    if idx is None:
        _audit("error", "NOT_FOUND", {"index_name": index_name}, db_id=db_id)
        return _err("NOT_FOUND", "Index not found or not ready", index_name=index_name)

    dim = idx.get("dim")
    if not isinstance(dim, int) or dim < 1:
        _audit("error", "CONFLICT", {"index_name": index_name}, db_id=db_id)
        return _err("CONFLICT", "Index has invalid dimension", index_name=index_name)
    if len(qv) != dim:
        _audit("error", "VALIDATION_ERROR", {"expected_dim": dim, "got_dim": len(qv)}, db_id=db_id)
        return _err("VALIDATION_ERROR", "query_vector length must equal index dim", expected_dim=dim, got_dim=len(qv))

    distance_metric = idx.get("distance_metric")
    prefix = idx.get("prefix") or ""
    if not isinstance(prefix, str):
        prefix = ""

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []

    now = _now_dt()

    def _key_active_not_expired(kr):
        if not isinstance(kr, dict):
            return False
        if kr.get("status") != "active":
            return False
        exp = _parse_dt(kr.get("expires_at"))
        return exp is None or exp > now

    # map key_id -> value row
    v_by_key = {}
    for v in values:
        if isinstance(v, dict) and isinstance(v.get("key_id"), str):
            v_by_key[v["key_id"]] = v

    candidates = []
    for kr in keys:
        if not isinstance(kr, dict):
            continue
        if kr.get("db_id") != db_id:
            continue
        if kr.get("key_type") != "hash":
            continue
        if not _key_active_not_expired(kr):
            continue
        kname = kr.get("key_name")
        if not isinstance(kname, str):
            continue
        if prefix and not kname.startswith(prefix):
            continue
        v = v_by_key.get(kr.get("id"))
        if not isinstance(v, dict):
            continue
        hv = v.get("hash_value")
        if not isinstance(hv, dict):
            continue
        blob = hv.get(vector_field)
        if not isinstance(blob, str) or not blob:
            continue
        candidates.append((kr, v, blob))

    def _decode_f32_base64(s):
        raw = base64.b64decode(s, validate=False)
        if len(raw) != dim * 4:
            return None
        return struct.unpack("<" + "f" * dim, raw)

    def _score(q, x):
        # return higher is better
        if distance_metric == "COSINE":
            dot = 0.0
            nq = 0.0
            nx = 0.0
            for a, b in zip(q, x):
                dot += a * b
                nq += a * a
                nx += b * b
            if nq <= 0.0 or nx <= 0.0:
                return -1e30
            return dot / (math.sqrt(nq) * math.sqrt(nx))
        if distance_metric == "IP":
            dot = 0.0
            for a, b in zip(q, x):
                dot += a * b
            return dot
        # L2 (smaller is better -> negate)
        s = 0.0
        for a, b in zip(q, x):
            d = a - b
            s += d * d
        return -s

    scored = []
    decode_fail = 0
    for kr, v, blob in candidates:
        try:
            vec = _decode_f32_base64(blob)
        except Exception:
            vec = None
        if vec is None:
            decode_fail += 1
            continue
        s = _score(qv, vec)
        scored.append((s, kr, v))

    scored.sort(key=lambda t: t[0], reverse=True)
    top = scored[:k]

    results = []
    for s, kr, v in top:
        hv = v.get("hash_value") if isinstance(v, dict) else None
        if not isinstance(hv, dict):
            hv = {}
        row = {"key": kr.get("key_name"), "score": s}
        if return_fields:
            for f in return_fields:
                row[f] = hv.get(f)
        results.append(row)

    _audit("ok", None, {"candidates": len(candidates), "decoded": len(scored), "decode_fail": decode_fail, "returned": len(results)}, db_id=db_id)
    return {"results": results, "k": k, "count": len(results), "index_name": index_name}

def hset(name, key, value, expire_seconds=None, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
