        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "hset"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None

        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = _now_dt()
        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        dbs = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not dbs:
            return None, _err("NOT_FOUND", "No Redis databases exist")

        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        candidates = []
        if isinstance(default_db_id, str) and default_db_id:
            candidates = [d for d in dbs if d.get("id") == default_db_id]
        else:
            candidates = [d for d in dbs if d.get("status") in ("active", "read_only")]
            if not candidates:
                candidates = [d for d in dbs if d.get("status") != "disabled"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No usable Redis database available")
        db = candidates[0]
        if db.get("status") == "disabled":
            return None, _err("INVALID_TRANSITION", "Default database is disabled", db_id=db.get("id"))
        return db, None

    # Validate
    if not isinstance(name, str) or not name:
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(key, str) or not key:
        _log("error", "VALIDATION_ERROR", {"field": "key"})
        return _err("VALIDATION_ERROR", "key must be a non-empty string", field="key")
    if not isinstance(value, (str, int, float)):
        _log("error", "VALIDATION_ERROR", {"field": "value"})
        return _err("VALIDATION_ERROR", "value must be a string, integer, or number", field="value")
    if expire_seconds is not None:
        if not isinstance(expire_seconds, int):
            _log("error", "VALIDATION_ERROR", {"field": "expire_seconds"})
            return _err("VALIDATION_ERROR", "expire_seconds must be an integer", field="expire_seconds")
        if expire_seconds < 1:
            _log("error", "VALIDATION_ERROR", {"field": "expire_seconds"})
            return _err("VALIDATION_ERROR", "expire_seconds must be >= 1", field="expire_seconds")

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], limerr["error"])
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], dberr["error"])
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []

    now = _now_dt()
    now_iso = _now_iso()

    # helper: mark expired actives with expires_at <= now
    for krow in keys:
        if not isinstance(krow, dict):
            continue
        if krow.get("db_id") != db_id:
            continue
        if krow.get("status") != "active":
            continue
        exp = _parse_dt(krow.get("expires_at"))
        if exp is not None and exp <= now:
            krow["status"] = "expired"
            krow["updated_at"] = now_iso

    # Find existing key by name in db
    existing = None
    for krow in keys:
        if isinstance(krow, dict) and krow.get("db_id") == db_id and krow.get("key_name") == name:
            existing = krow
            break

    if existing and existing.get("status") == "active" and existing.get("key_type") != "hash":
        _log("error", "CONFLICT", {"reason": "WRONGTYPE", "expected": "hash", "actual": existing.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="hash", actual=existing.get("key_type"))

    # Upsert key
    if existing and existing.get("status") == "active":
        key_row = existing
    else:
        key_row = {
            "id": "rkey_" + uuid.uuid4().hex,
            "db_id": db_id,
            "key_name": name,
            "key_type": "hash",
            "encoding": None,
            "ttl_seconds": None,
            "expires_at": None,
            "status": "active",
            "approx_size_bytes": None,
            "last_accessed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        keys.append(key_row)

    # Apply TTL
    if expire_seconds is not None:
        key_row["ttl_seconds"] = expire_seconds
        key_row["expires_at"] = (now + datetime.timedelta(seconds=expire_seconds)).replace(microsecond=0).isoformat() + "Z"
    # If not provided, leave TTL unchanged (consistent with Redis HSET which doesn't clear TTL)
    key_row["updated_at"] = now_iso
    key_row["last_accessed_at"] = now_iso

    # Upsert value row for hash
    key_id = key_row.get("id")
    vrow = None
    for r in values:
        if isinstance(r, dict) and r.get("key_id") == key_id:
            vrow = r
            break
    if vrow is None:
        vrow = {
            "id": "rval_" + uuid.uuid4().hex,
            "key_id": key_id,
            "db_id": db_id,
            "string_value": None,
            "hash_value": {},
            "list_value": None,
            "set_value": None,
            "zset_value": None,
            "stream_value": None,
            "json_document": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        values.append(vrow)

    if not isinstance(vrow.get("hash_value"), dict):
        vrow["hash_value"] = {}
    existed_field = 1 if key in vrow["hash_value"] else 0
    # store scalar values; keep numbers as numbers (JSON)
    vrow["hash_value"][key] = value
    vrow["updated_at"] = now_iso

    _save("redis_keys.json", keys)
    _save("redis_values.json", values)

    _log("ok", None, {"name": name, "field": key, "updated": True, "new_field": (existed_field == 0)}, db_id=db_id)
    # Redis HSET returns number of fields added (0/1)
    return 0 if existed_field else 1

