            continue
        key_row = krow
        break

    if key_row is None:
        _log("ok", None, {"name": name, "deleted_fields": 0}, db_id=db_id)
        return 0

    if key_row.get("key_type") != "hash":
        _log("error", "CONFLICT", {"reason": "WRONGTYPE", "expected": "hash", "actual": key_row.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="hash", actual=key_row.get("key_type"))

    key_id = key_row.get("id")
    vrow = None
    for r in values:
        if isinstance(r, dict) and r.get("key_id") == key_id:
            vrow = r
            break

    if not vrow or not isinstance(vrow.get("hash_value"), dict):
        _log("ok", None, {"name": name, "deleted_fields": 0}, db_id=db_id)
        return 0

    if key in vrow["hash_value"]:
        del vrow["hash_value"][key]
        vrow["updated_at"] = now_iso
        key_row["updated_at"] = now_iso
        key_row["last_accessed_at"] = now_iso
        _save("redis_keys.json", keys)
        _save("redis_values.json", values)
        _log("ok", None, {"name": name, "deleted_fields": 1}, db_id=db_id)
        return 1

    _log("ok", None, {"name": name, "deleted_fields": 0}, db_id=db_id)
    return 0

