        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(vector_field, str) or not vector_field.strip():
        _log("error", "VALIDATION_ERROR", {"field": "vector_field"})
        return _err("VALIDATION_ERROR", "vector_field must be a non-empty string", field="vector_field")
    if not isinstance(vector, list):
        _log("error", "VALIDATION_ERROR", {"field": "vector"})
        return _err("VALIDATION_ERROR", "vector must be an array", field="vector")

    # Accept either numeric array OR a single base64 float32 blob string (common in this datastore)
    floats = None
    if len(vector) == 1 and isinstance(vector[0], str) and vector[0].strip():
        b64 = vector[0].strip()
        try:
            raw = base64.b64decode(b64, validate=False)
            if len(raw) % 4 != 0:
                _log("error", "VALIDATION_ERROR", {"field": "vector", "reason": "base64 length not multiple of 4 bytes"})
                return _err("VALIDATION_ERROR", "Invalid vector encoding: decoded byte length must be a multiple of 4", field="vector")
            n = len(raw) // 4
            floats = list(struct.unpack("<" + "f" * n, raw)) if n else []
        except Exception:
            _log("error", "VALIDATION_ERROR", {"field": "vector"})
            return _err("VALIDATION_ERROR", "Invalid 'vector': could not decode base64 float32 blob", field="vector")
    else:
        floats = []
        for i, el in enumerate(vector):
            if isinstance(el, bool) or el is None:
                _log("error", "VALIDATION_ERROR", {"field": "vector", "index": i})
                return _err("VALIDATION_ERROR", "Invalid 'vector': all elements must be numbers.", index=i)
            if isinstance(el, (int, float)):
                floats.append(float(el))
            else:
                _log("error", "VALIDATION_ERROR", {"field": "vector", "index": i})
                return _err("VALIDATION_ERROR", "Invalid 'vector': all elements must be numbers.", index=i)

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", limit_err["error"]["code"])
        return limit_err

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"])
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    vals = _load("redis_values.json")
    if not isinstance(vals, list):
        vals = []

    now = _now_dt()

    # locate key
    key_row = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break
    if not key_row or key_row.get("status") != "active":
        _log("error", "NOT_FOUND", {"key": name}, db_id=db_id)
        return _err("NOT_FOUND", "Key not found or not active", key=name)

    exp_dt = _parse_dt(key_row.get("expires_at"))
    if exp_dt and exp_dt <= now:
        key_row["status"] = "expired"
        key_row["updated_at"] = _now_iso()
        _save("redis_keys.json", keys)
        _log("error", "NOT_FOUND", {"key": name, "reason": "expired"}, db_id=db_id)
        return _err("NOT_FOUND", "Key not found or not active", key=name)

    if key_row.get("key_type") != "hash":
        _log("error", "VALIDATION_ERROR", {"key": name, "expected": "hash", "actual": key_row.get("key_type")}, db_id=db_id)
        return _err("VALIDATION_ERROR", "WRONGTYPE Operation against a key holding the wrong kind of value", key=name, expected_type="hash", actual_type=key_row.get("key_type"))

    key_id = key_row.get("id")
    if not isinstance(key_id, str) or not key_id:
        _log("error", "CONFLICT", {"key": name, "reason": "missing key id"}, db_id=db_id)
        return _err("CONFLICT", "Corrupt key record: missing id", key=name)

    # find/create value row
    val_row = None
    for v in vals:
        if isinstance(v, dict) and v.get("key_id") == key_id:
            val_row = v
            break
    if val_row is None:
        val_row = {
            "id": "rval_" + uuid.uuid4().hex,
            "key_id": key_id,
            "db_id": db_id,
            "string_value": None,
            "hash_value": {},
            "list_value": None,
            "set_value": None,
            "zset_value": None,
            "stream_value": None,
            "json_document": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        vals.append(val_row)

    if not isinstance(val_row.get("hash_value"), dict) or val_row.get("hash_value") is None:
        val_row["hash_value"] = {}

    blob = base64.b64encode(struct.pack("<" + "f" * len(floats), *floats)).decode("ascii")
    val_row["hash_value"][vector_field] = blob
    val_row["updated_at"] = _now_iso()

    key_row["updated_at"] = _now_iso()
    key_row["last_accessed_at"] = _now_iso()

    _save("redis_values.json", vals)
    _save("redis_keys.json", keys)

    _log("success", None, {"key": name, "vector_field": vector_field, "dim": len(floats)}, db_id=db_id)
    return {"ok": True, "name": name, "vector_field": vector_field, "dim": len(floats)}

