            logs = []
        now = _now_dt()
        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        dbs = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not dbs:
            return None, _err("NOT_FOUND", "No Redis databases exist")

        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        candidates = []
        if isinstance(default_db_id, str) and default_db_id:
            candidates = [d for d in dbs if d.get("id") == default_db_id]
        else:
            flagged = [d for d in dbs if d.get("status") in ("active", "read_only") and (d.get("is_default") is True or d.get("default") is True)]
            if flagged:
                candidates = flagged
            else:
                ar = [d for d in dbs if d.get("status") in ("active", "read_only")]
                if ar:
                    with_num = [d for d in ar if isinstance(d.get("db_number"), int)]
                    candidates = sorted(with_num, key=lambda x: x["db_number"]) if with_num else ar

        if not candidates:
            return None, _err("UNAUTHORIZED", "No configured default database available for this operation")

        db = candidates[0]
        if db.get("status") == "disabled":
            return None, _err("UNAUTHORIZED", "Default Redis database is disabled", db_id=db.get("id"))
        return db, None

    if vector_field is None:
        vector_field = "vector"

    if not isinstance(name, str) or not name.strip():
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(vector_field, str) or not vector_field.strip():
        _log("error", "VALIDATION_ERROR", {"field": "vector_field"})
        return _err("VALIDATION_ERROR", "vector_field must be a non-empty string", field="vector_field")

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", limit_err["error"]["code"])
        return limit_err

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"])
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    vals = _load("redis_values.json")
    if not isinstance(vals, list):
        vals = []

    now = _now_dt()

    key_row = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break
    if not key_row or key_row.get("status") != "active":
        _log("error", "NOT_FOUND", {"key": name}, db_id=db_id)
        return _err("NOT_FOUND", "Key not found or not active", key=name)

    exp_dt = _parse_dt(key_row.get("expires_at"))
    if exp_dt and exp_dt <= now:
        key_row["status"] = "expired"
        key_row["updated_at"] = _now_iso()
        _save("redis_keys.json", keys)
        _log("error", "NOT_FOUND", {"key": name, "reason": "expired"}, db_id=db_id)
        return _err("NOT_FOUND", "Key not found or not active", key=name)

    if key_row.get("key_type") != "hash":
        _log("error", "VALIDATION_ERROR", {"key": name, "expected": "hash", "actual": key_row.get("key_type")}, db_id=db_id)
        return _err("VALIDATION_ERROR", "WRONGTYPE Operation against a key holding the wrong kind of value", key=name, expected_type="hash", actual_type=key_row.get("key_type"))

    key_id = key_row.get("id")
    val_row = None
    for v in vals:
        if isinstance(v, dict) and v.get("key_id") == key_id:
            val_row = v
            break
    if not val_row or not isinstance(val_row.get("hash_value"), dict):
        _log("error", "NOT_FOUND", {"key": name, "field": vector_field}, db_id=db_id)
        return _err("NOT_FOUND", "Vector field not found", key=name, field=vector_field)

    blob = val_row["hash_value"].get(vector_field)
    if not isinstance(blob, str) or not blob:
        _log("error", "NOT_FOUND", {"key": name, "field": vector_field}, db_id=db_id)
        return _err("NOT_FOUND", "Vector field not found", key=name, field=vector_field)

    try:
        raw = base64.b64decode(blob, validate=False)
    except Exception:
        _log("error", "CONFLICT", {"key": name, "field": vector_field, "reason": "invalid base64"}, db_id=db_id)
        return _err("CONFLICT", "Stored vector is not valid base64", key=name, field=vector_field)

    if len(raw) % 4 != 0:
        _log("error", "CONFLICT", {"key": name, "field": vector_field, "reason": "invalid float32 blob length"}, db_id=db_id)
        return _err("CONFLICT", "Stored vector blob length is invalid", key=name, field=vector_field)

    n = len(raw) // 4
    try:
        vec = list(struct.unpack("<" + "f" * n, raw)) if n else []
    except Exception:
        _log("error", "CONFLICT", {"key": name, "field": vector_field, "reason": "unpack failed"}, db_id=db_id)
        return _err("CONFLICT", "Stored vector blob could not be decoded", key=name, field=vector_field)

    key_row["last_accessed_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()
    _save("redis_keys.json", keys)

    _log("success", None, {"key": name, "field": vector_field, "dim": len(vec)}, db_id=db_id)
    return {"name": name, "vector_field": vector_field, "vector": vec, "dim": len(vec)}

def lpush(name, value, expire=None, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "lpush"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_dt()
        rpm = limits.get("write_requests_per_minute", limits.get("requests_per_minute"))
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        if isinstance(default_db_id, str) and default_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == default_db_id:
                    if d.get("status") == "disabled":
                        return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=default_db_id)
                    return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    if not isinstance(name, str) or not name:
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    if expire is not None:
        if not isinstance(expire, int) or expire < 1:
            _log("error", "VALIDATION_ERROR", {"field": "expire"})
            return _err("VALIDATION_ERROR", "expire must be an integer >= 1 or null", field="expire")

    # Accept strings/ints/floats as list items; store as string representation (Redis-like)
    if value is None or isinstance(value, (dict, list)):
        _log("error", "VALIDATION_ERROR", {"field": "value"})
        return _err("VALIDATION_ERROR", "value must be a scalar (string/number)", field="value")
    if isinstance(value, bool):
        # bool is scalar but often unwanted; still accept by stringifying
        val_str = "1" if value else "0"
    else:
        val_str = str(value)

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []

    now = _now_dt()

    def _is_active_not_expired(r):
        if not isinstance(r, dict):
            return False
        if r.get("status") != "active":
            return False
        exp = _parse_dt(r.get("expires_at"))
        return exp is None or exp > now

    key_row = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break

    if key_row is not None and _is_active_not_expired(key_row) and key_row.get("key_type") != "list":
        _log("error", "CONFLICT", {"rule": "WRONGTYPE", "expected": "list", "found": key_row.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="list", found=key_row.get("key_type"))

    # Upsert key
    created = False
    if key_row is None or key_row.get("status") in ("deleted", "expired") or not _is_active_not_expired(key_row):
        created = True
        key_id = "rkey_" + uuid.uuid4().hex[:26]
        key_row = {
            "id": key_id,
            "db_id": db_id,
            "key_name": name,
            "key_type": "list",
            "encoding": "utf8",
            "ttl_seconds": None,
            "expires_at": None,
            "status": "active",
            "approx_size_bytes": None,
            "last_accessed_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        keys.append(key_row)
    else:
        key_row["status"] = "active"
        key_row["key_type"] = "list"
        key_row["last_accessed_at"] = _now_iso()
        key_row["updated_at"] = _now_iso()

    # Handle TTL
    if expire is not None:
        key_row["ttl_seconds"] = expire
        key_row["expires_at"] = (now + datetime.timedelta(seconds=expire)).isoformat() + "Z"
    elif created is False:
        # do not change ttl when expire is None per typical LPUSH? tool says optionally refresh when expire provided.
        pass

    # Upsert list value row
    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
            vrow = v
            break
    if vrow is None:
        vrow = {
            "id": "rval_" + uuid.uuid4().hex[:26],
            "key_id": key_row["id"],
            "db_id": db_id,
            "string_value": None,
            "hash_value": None,
            "list_value": [],
            "set_value": None,
            "zset_value": None,
            "stream_value": None,
            "json_document": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        values.append(vrow)
    else:
        vrow["updated_at"] = _now_iso()
        if vrow.get("list_value") is None:
            vrow["list_value"] = []

    if not isinstance(vrow.get("list_value"), list):
        _log("error", "CONFLICT", {"rule": "value_column_mismatch"}, db_id=db_id)
        return _err("CONFLICT", "Stored value is not a list for this key", key=name)

    vrow["list_value"].insert(0, val_str)
    vrow["updated_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()

    _save("redis_keys.json", keys)
    _save("redis_values.json", values)

    new_len = len(vrow["list_value"])
    _log("ok", None, {"key": name, "len": new_len}, db_id=db_id)
    return {"key": name, "length": new_len}

