    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_dt()
        rpm = limits.get("write_requests_per_minute", limits.get("requests_per_minute"))
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        if isinstance(default_db_id, str) and default_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == default_db_id:
                    if d.get("status") == "disabled":
                        return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=default_db_id)
                    return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    if not isinstance(name, str) or not name:
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    if expire is not None:
        if not isinstance(expire, int) or expire < 1:
            _log("error", "VALIDATION_ERROR", {"field": "expire"})
            return _err("VALIDATION_ERROR", "expire must be an integer >= 1 or null", field="expire")

    if value is None or isinstance(value, (dict, list)):
        _log("error", "VALIDATION_ERROR", {"field": "value"})
        return _err("VALIDATION_ERROR", "value must be a scalar (string/number)", field="value")
    if isinstance(value, bool):
        val_str = "1" if value else "0"
    else:
        val_str = str(value)

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []

    now = _now_dt()

    def _is_active_not_expired(r):
        if not isinstance(r, dict):
            return False
        if r.get("status") != "active":
            return False
        exp = _parse_dt(r.get("expires_at"))
        return exp is None or exp > now

    key_row = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break

    if key_row is not None and _is_active_not_expired(key_row) and key_row.get("key_type") != "list":
        _log("error", "CONFLICT", {"rule": "WRONGTYPE", "expected": "list", "found": key_row.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="list", found=key_row.get("key_type"))

    created = False
    if key_row is None or key_row.get("status") in ("deleted", "expired") or not _is_active_not_expired(key_row):
        created = True
        key_id = "rkey_" + uuid.uuid4().hex[:26]
        key_row = {
            "id": key_id,
            "db_id": db_id,
            "key_name": name,
            "key_type": "list",
            "encoding": "utf8",
            "ttl_seconds": None,
            "expires_at": None,
            "status": "active",
            "approx_size_bytes": None,
            "last_accessed_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        keys.append(key_row)
    else:
        key_row["status"] = "active"
        key_row["key_type"] = "list"
        key_row["last_accessed_at"] = _now_iso()
        key_row["updated_at"] = _now_iso()

    if expire is not None:
        key_row["ttl_seconds"] = expire
        key_row["expires_at"] = (now + datetime.timedelta(seconds=expire)).isoformat() + "Z"

    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
            vrow = v
            break
    if vrow is None:
        vrow = {
            "id": "rval_" + uuid.uuid4().hex[:26],
            "key_id": key_row["id"],
            "db_id": db_id,
            "string_value": None,
            "hash_value": None,
            "list_value": [],
            "set_value": None,
            "zset_value": None,
            "stream_value": None,
            "json_document": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        values.append(vrow)
    else:
        vrow["updated_at"] = _now_iso()
        if vrow.get("list_value") is None:
            vrow["list_value"] = []

    if not isinstance(vrow.get("list_value"), list):
        _log("error", "CONFLICT", {"rule": "value_column_mismatch"}, db_id=db_id)
        return _err("CONFLICT", "Stored value is not a list for this key", key=name)

    vrow["list_value"].append(val_str)
    vrow["updated_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()

    _save("redis_keys.json", keys)
    _save("redis_values.json", values)

    new_len = len(vrow["list_value"])
    _log("ok", None, {"key": name, "len": new_len}, db_id=db_id)
    return {"key": name, "length": new_len}

def lpop(name, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "lpop"
    cred = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _log(status_code):
        logs = _load("redis_request_logs.json")
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": cred,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now()
        })
        _save("redis_request_logs.json", logs)

    def _resolve_default_db(databases):
        active = [d for d in databases if isinstance(d, dict) and d.get("status") in ("active", "read_only")]
        if not active:
            return None
        for d in active:
            if d.get("is_default") is True or d.get("default") is True:
                return d
        active2 = [d for d in active if isinstance(d.get("db_number"), int)]
        if active2:
            return sorted(active2, key=lambda x: x["db_number"])[0]
        return active[0]

    try:
        if not isinstance(name, str) or not name.strip():
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a non-empty string")

        dbs = _load("redis_databases.json")
        default_db = _resolve_default_db(dbs)
        if not default_db:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No usable default database is configured")
        if default_db.get("status") == "disabled":
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Default database is disabled")
        db_id = default_db.get("id")

        keys = _load("redis_keys.json")
        vals = _load("redis_values.json")
        now_dt = datetime.datetime.utcnow().replace(microsecond=0)
        ts = _now()

        key_row = None
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("db_id") == db_id and k.get("key_name") == name and k.get("status") == "active":
                # skip expired
                exp = _parse_dt(k.get("expires_at"))
                if exp is not None and exp <= now_dt:
                    key_row = None
                    break
                key_row = k
                break

        if not key_row:
            _log("ok")
            return {"value": None}

        if key_row.get("key_type") != "list":
            _log("CONFLICT")
            return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value")

        vrow = None
        for v in vals:
            if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
                vrow = v
                break

        if not vrow or not isinstance(vrow.get("list_value"), list) or len(vrow["list_value"]) == 0:
            # Consistent behavior: keep key but return null for empty list
            key_row["last_accessed_at"] = ts
            key_row["updated_at"] = ts
            _save("redis_keys.json", keys)
            _log("ok")
            return {"value": None}

        popped = vrow["list_value"].pop(0)
        vrow["updated_at"] = ts
        key_row["last_accessed_at"] = ts
        key_row["updated_at"] = ts

        _save("redis_values.json", vals)
        _save("redis_keys.json", keys)

        _log("ok")
        return {"value": popped}
    except Exception as e:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def rpop(name, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # --- auth/context: select a usable default DB (ambient auth) ---
    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
            default_db = d
            break
    if default_db is None:
        # If a default exists but is disabled => UNAUTHORIZED, else UNAUTHORIZED (no usable context)
        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                default_db = d
                break

    # --- rate limiting / request log (best-effort within this tool) ---
    logs = _load("redis_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # Simple global rate limit: 120 req/min
    window_s = 60
    limit = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        if not isinstance(r, dict): 
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                if ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                else:
                    dt = datetime.datetime.fromisoformat(ts)
                if dt >= cutoff:
                    recent += 1
            except Exception:
                pass
    if recent >= limit:
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "rpop",
            "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
            "status": "RATE_LIMIT",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("RATE_LIMIT", "Request rate limit exceeded")

    if not isinstance(name, str) or not name:
        status = "VALIDATION_ERROR"
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "rpop",
            "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
            "status": status,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "name must be a non-empty string")

    if not isinstance(default_db, dict) or default_db.get("status") == "disabled":
        status = "UNAUTHORIZED"
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "rpop",
            "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
            "status": status,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("UNAUTHORIZED", "Not authorized for the default database")

    db_id = default_db["id"]

    keys = _load("redis_keys.json")
    values = _load("redis_values.json")
    if not isinstance(keys, list): keys = []
    if not isinstance(values, list): values = []

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_expired(key_row):
        if not isinstance(key_row, dict):
            return False
        if key_row.get("status") != "active":
            return True
        exp = _parse_dt(key_row.get("expires_at"))
        return (exp is not None and exp <= now)

    # find active key by name in default db
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("db_id") == db_id and k.get("key_name") == name:
            key_row = k
            break

    # if missing, or expired, or not active -> return null (Redis-style)
    if key_row is None or _is_expired(key_row):
        # if expired but still marked active, mark it expired for consistency
        if isinstance(key_row, dict) and key_row.get("status") == "active" and _is_expired(key_row):
            # transition active -> expired allowed
            key_row["status"] = "expired"
            key_row["updated_at"] = now_iso
            _save("redis_keys.json", keys)

        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "rpop",
            "db_id": db_id,
            "status": "OK",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return {"result": None, "db_id": db_id}

    # WRONGTYPE if not list
    if key_row.get("key_type") != "list":
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "rpop",
            "db_id": db_id,
            "status": "CONFLICT",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value")

    # load value row
    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
            vrow = v
            break
    if vrow is None:
        # treat as empty list
        key_row["last_accessed_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("redis_keys.json", keys)
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "rpop",
            "db_id": db_id,
            "status": "OK",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return {"result": None, "db_id": db_id}

    lst = vrow.get("list_value")
    if not isinstance(lst, list) or len(lst) == 0:
        key_row["last_accessed_at"] = now_iso
        key_row["updated_at"] = now_iso
        vrow["updated_at"] = now_iso
        _save("redis_keys.json", keys)
        _save("redis_values.json", values)
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "rpop",
            "db_id": db_id,
            "status": "OK",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return {"result": None, "db_id": db_id}

    elem = lst.pop()
    vrow["list_value"] = lst
    vrow["updated_at"] = now_iso
    key_row["last_accessed_at"] = now_iso
    key_row["updated_at"] = now_iso

    _save("redis_values.json", values)
    _save("redis_keys.json", keys)

    req_row = {
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "rpop",
        "db_id": db_id,
        "status": "OK",
        "timestamp": now_iso,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    logs.append(req_row)
    _save("redis_request_logs.json", logs)
    return {"result": elem, "db_id": db_id}

