            _save("redis_keys.json", keys)
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "lrange",
            "db_id": db_id,
            "status": "OK",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return {"result": [], "db_id": db_id, "name": name, "start": start, "stop": stop}

    if key_row.get("key_type") != "list":
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "lrange",
            "db_id": db_id,
            "status": "CONFLICT",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value")

    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
            vrow = v
            break
    lst = vrow.get("list_value") if isinstance(vrow, dict) else []
    if not isinstance(lst, list):
        lst = []

    n = len(lst)
    def _norm_index(i, default_if_neg_inf=0):
        # Redis-style: negatives are from end.
        if i < 0:
            i = n + i
        return i

    s = _norm_index(start)
    e = _norm_index(stop)
    # clamp
    if s < 0: s = 0
    if e < 0:  # still negative after normalization implies before start
        result = []
    else:
        if s >= n:
            result = []
        else:
            if e >= n:
                e = n - 1
            if e < s:
                result = []
            else:
                # stop inclusive
                result = lst[s:e + 1]

    key_row["last_accessed_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("redis_keys.json", keys)

    req_row = {
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "lrange",
        "db_id": db_id,
        "status": "OK",
        "timestamp": now_iso,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    logs.append(req_row)
    _save("redis_request_logs.json", logs)
    return {"result": result, "db_id": db_id, "name": name, "start": start, "stop": stop, "length": n}

def llen(name, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "llen"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_dt()
        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        if isinstance(default_db_id, str) and default_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == default_db_id:
                    if d.get("status") == "disabled":
                        return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=default_db_id)
                    return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    if not isinstance(name, str) or not name:
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []

    now = _now_dt()

    def _is_active_not_expired(r):
        if not isinstance(r, dict):
            return False
        if r.get("status") != "active":
            return False
        exp = _parse_dt(r.get("expires_at"))
        return exp is None or exp > now

    key_row = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break

    if key_row is None or not _is_active_not_expired(key_row) or key_row.get("status") != "active":
        _log("error", "NOT_FOUND", {"key": name}, db_id=db_id)
        return _err("NOT_FOUND", "Key not found", key=name)

    if key_row.get("key_type") != "list":
        _log("error", "CONFLICT", {"rule": "WRONGTYPE", "expected": "list", "found": key_row.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="list", found=key_row.get("key_type"))

    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
            vrow = v
            break

    if vrow is None:
        # list key exists but missing value row -> treat as empty list
        length = 0
    else:
        lv = vrow.get("list_value")
        length = len(lv) if isinstance(lv, list) else 0

    _log("ok", None, {"key": name, "len": length}, db_id=db_id)
    return {"key": name, "length": length}

def set(key, value, expiration=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
            default_db = d
            break
    if default_db is None:
        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                default_db = d
                break

    logs = _load("redis_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    limit = 120
    cutoff = now - datetime.timedelta(seconds=window_s)
    recent = 0
    for r in logs:
        if not isinstance(r, dict): 
            continue
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
                if dt >= cutoff:
                    recent += 1
            except Exception:
                pass
    if recent >= limit:
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "set",
            "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
            "status": "RATE_LIMIT",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("RATE_LIMIT", "Request rate limit exceeded")

    if not isinstance(key, str) or not key:
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "set",
            "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
            "status": "VALIDATION_ERROR",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "key must be a non-empty string")

    if not isinstance(value, (str, int, float)):
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "set",
            "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
            "status": "VALIDATION_ERROR",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "value must be a string, integer, or number")

    if expiration is not None:
        if not isinstance(expiration, int):
            req_row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "set",
                "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
                "status": "VALIDATION_ERROR",
                "timestamp": now_iso,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(req_row)
            _save("redis_request_logs.json", logs)
            return _err("VALIDATION_ERROR", "expiration must be an integer when provided")
        if expiration < 1:
            req_row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "set",
                "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
                "status": "VALIDATION_ERROR",
                "timestamp": now_iso,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(req_row)
            _save("redis_request_logs.json", logs)
            return _err("VALIDATION_ERROR", "expiration must be >= 1")

    if not isinstance(default_db, dict) or default_db.get("status") == "disabled":
        req_row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "set",
            "db_id": default_db.get("id") if isinstance(default_db, dict) else None,
            "status": "UNAUTHORIZED",
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(req_row)
        _save("redis_request_logs.json", logs)
        return _err("UNAUTHORIZED", "Not authorized for the default database")

    db_id = default_db["id"]
    keys = _load("redis_keys.json")
    values = _load("redis_values.json")
    if not isinstance(keys, list): keys = []
    if not isinstance(values, list): values = []

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_expired(key_row):
        if not isinstance(key_row, dict):
            return False
        if key_row.get("status") != "active":
            return True
        exp = _parse_dt(key_row.get("expires_at"))
        return (exp is not None and exp <= now)

    # If existing key is expired, mark it expired so the upsert will create/overwrite cleanly
    existing = None
    for k in keys:
        if isinstance(k, dict) and k.get("db_id") == db_id and k.get("key_name") == key:
            existing = k
            break
    if isinstance(existing, dict) and existing.get("status") == "active" and _is_expired(existing):
        existing["status"] = "expired"
        existing["updated_at"] = now_iso

    # upsert key with type 'string'
    if existing is None or existing.get("status") in ("deleted", "expired"):
        key_id = "rkey_" + uuid.uuid4().hex
        new_key = {
            "id": key_id,
            "db_id": db_id,
            "key_name": key,
            "key_type": "string",
            "encoding": None,
            "ttl_seconds": None,
            "expires_at": None,
            "status": "active",
            "approx_size_bytes": None,
            "last_accessed_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        keys.append(new_key)
        existing = new_key
    else:
        # key exists and is active (non-expired)
        if existing.get("status") != "active":
            # should not happen due to above, but be safe
            req_row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "set",
                "db_id": db_id,
                "status": "CONFLICT",
                "timestamp": now_iso,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(req_row)
            _save("redis_request_logs.json", logs)
            return _err("CONFLICT", "Key exists in a non-writable state")
        # Redis SET overwrites regardless of old type; this service enforces upsert with key_type='string'
        existing["key_type"] = "string"
        existing["last_accessed_at"] = now_iso
        existing["updated_at"] = now_iso

    # set/clear TTL
    if expiration is None:
        existing["ttl_seconds"] = None
        existing["expires_at"] = None
    else:
        existing["ttl_seconds"] = int(expiration)
        exp_at = now + datetime.timedelta(seconds=int(expiration))
        existing["expires_at"] = exp_at.replace(microsecond=0).isoformat() + "Z"

    # upsert values row unique(key_id)
    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == existing.get("id"):
            vrow = v
            break
    if vrow is None:
        vrow = {
            "id": "rval_" + uuid.uuid4().hex,
            "key_id": existing["id"],
            "db_id": db_id,
            "string_value": None,
            "hash_value": None,
            "list_value": None,
            "set_value": None,
            "zset_value": None,
            "stream_value": None,
            "json_document": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        values.append(vrow)

    # enforce: only string_value non-null for key_type='string'
    vrow["string_value"] = str(value) if not isinstance(value, str) else value
    vrow["hash_value"] = None
    vrow["list_value"] = None
    vrow["set_value"] = None
    vrow["zset_value"] = None
    vrow["stream_value"] = None
    vrow["json_document"] = None
    vrow["db_id"] = db_id
    vrow["updated_at"] = now_iso

    _save("redis_keys.json", keys)
    _save("redis_values.json", values)

    req_row = {
        "id": "req_" + uuid.uuid4().hex,
        "endpoint": "set",
        "db_id": db_id,
        "status": "OK",
        "timestamp": now_iso,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    logs.append(req_row)
    _save("redis_request_logs.json", logs)

    return {
        "result": "OK",
        "db_id": db_id,
        "key": key,
        "expiration": expiration,
    }

def get(key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get"
    used_credential = None

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _record(status, error_code=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential": used_credential,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(_now()),
        }
        logs.append(row)
        _save("redis_request_logs.json", logs)

    try:
        if not isinstance(key, str) or key == "":
            res = _err("VALIDATION_ERROR", "key must be a non-empty string")
            _record("error", "VALIDATION_ERROR")
            return res

        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        default_db = None
        for db in dbs:
            if isinstance(db, dict) and db.get("status") == "active":
                default_db = db
                break
        if default_db is None:
            res = _err("UNAUTHORIZED", "No active default database available")
            _record("error", "UNAUTHORIZED")
            return res
        if default_db.get("status") == "disabled":
            res = _err("UNAUTHORIZED", "Default database is disabled")
            _record("error", "UNAUTHORIZED")
            return res

        now = _now()
        keys = _load("redis_keys.json")
        if not isinstance(keys, list):
            keys = []
        krow = None
        for r in keys:
            if not isinstance(r, dict):
                continue
            if r.get("db_id") != default_db.get("id"):
                continue
            if r.get("key_name") != key:
                continue
            if r.get("status") != "active":
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            krow = r
            break

        if krow is None:
            _record("ok", None)
            return None

        if krow.get("key_type") != "string":
            res = _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="string", actual=krow.get("key_type"))
            _record("error", "CONFLICT")
            return res

        values = _load("redis_values.json")
        if not isinstance(values, list):
            values = []
        vrow = None
        for v in values:
            if not isinstance(v, dict):
                continue
            if v.get("key_id") == krow.get("id"):
                vrow = v
                break

        # Update last_accessed_at on key (and updated_at)
        touched = False
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == krow.get("id"):
                keys[i] = dict(r)
                keys[i]["last_accessed_at"] = _iso(now)
                keys[i]["updated_at"] = _iso(now)
                touched = True
                break
        if touched:
            _save("redis_keys.json", keys)

        if vrow is None:
            _record("ok", None)
            return None

        _record("ok", None)
        return vrow.get("string_value")
    except Exception as e:
        res = _err("CONFLICT", "Internal error", detail=str(e))
        _record("error", "CONFLICT")
        return res

