            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_dt()
        rpm = limits.get("write_requests_per_minute", limits.get("requests_per_minute"))
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        if isinstance(default_db_id, str) and default_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("id") == default_db_id:
                    if d.get("status") == "disabled":
                        return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=default_db_id)
                    return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    def _set_path(doc, p, val):
        # Support minimal JSONPath-ish:
        # - "." or "$" sets root
        # - "a.b.c" sets nested objects creating dicts
        # - if path doesn't start with "$", treat as dot path
        if p in (".", "$", "$."):
            return val
        if p.startswith("$."):
            p = p[2:]
        if p.startswith("$"):
            p = p[1:]
            if p.startswith("."):
                p = p[1:]
        parts = [x for x in p.split(".") if x != ""]
        if not parts:
            return val
        if doc is None or not isinstance(doc, (dict, list)):
            doc = {}
        cur = doc
        for i, part in enumerate(parts):
            last = (i == len(parts) - 1)
            if last:
                if isinstance(cur, dict):
                    cur[part] = val
                else:
                    # cannot set into list with string key; replace root
                    return val
            else:
                if isinstance(cur, dict):
                    nxt = cur.get(part)
                    if not isinstance(nxt, dict):
                        nxt = {}
                        cur[part] = nxt
                    cur = nxt
                else:
                    # cannot traverse list with string keys; replace root
                    return val
        return doc

    if not isinstance(name, str) or not name:
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if not isinstance(path, str) or not path:
        _log("error", "VALIDATION_ERROR", {"field": "path"})
        return _err("VALIDATION_ERROR", "path must be a non-empty string", field="path")
    if expire_seconds is not None:
        if not isinstance(expire_seconds, int) or expire_seconds < 1:
            _log("error", "VALIDATION_ERROR", {"field": "expire_seconds"})
            return _err("VALIDATION_ERROR", "expire_seconds must be an integer >= 1 or null", field="expire_seconds")

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []

    now = _now_dt()

    # upsert json key
    key_row = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break

    def _is_active_not_expired(r):
        if not isinstance(r, dict):
            return False
        if r.get("status") != "active":
            return False
        exp = _parse_dt(r.get("expires_at"))
        return exp is None or exp > now

    if key_row is not None and _is_active_not_expired(key_row) and key_row.get("key_type") != "json":
        _log("error", "CONFLICT", {"rule": "WRONGTYPE", "expected": "json", "found": key_row.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="json", found=key_row.get("key_type"))

    if key_row is None or key_row.get("status") in ("deleted", "expired") or not _is_active_not_expired(key_row):
        key_row = {
            "id": "rkey_" + uuid.uuid4().hex[:26],
            "db_id": db_id,
            "key_name": name,
            "key_type": "json",
            "encoding": "json",
            "ttl_seconds": None,
            "expires_at": None,
            "status": "active",
            "approx_size_bytes": None,
            "last_accessed_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        keys.append(key_row)
    else:
        key_row["status"] = "active"
        key_row["key_type"] = "json"
        key_row["last_accessed_at"] = _now_iso()
        key_row["updated_at"] = _now_iso()

    if expire_seconds is not None:
        key_row["ttl_seconds"] = expire_seconds
        key_row["expires_at"] = (now + datetime.timedelta(seconds=expire_seconds)).isoformat() + "Z"

    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
            vrow = v
            break
    if vrow is None:
        vrow = {
            "id": "rval_" + uuid.uuid4().hex[:26],
            "key_id": key_row["id"],
            "db_id": db_id,
            "string_value": None,
            "hash_value": None,
            "list_value": None,
            "set_value": None,
            "zset_value": None,
            "stream_value": None,
            "json_document": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        values.append(vrow)

    doc = vrow.get("json_document")
    # if existing doc is None, treat as empty object unless setting root
    new_doc = _set_path(doc, path, value)
    vrow["json_document"] = new_doc
    vrow["updated_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()

    _save("redis_keys.json", keys)
    _save("redis_values.json", values)

    _log("ok", None, {"key": name, "path": path}, db_id=db_id)
    return {"status": "success", "key": name, "path": path}

def json_get(name, path="$", **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "json_get"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _enforce_limits():
        limits = _load("redis_service_limits.json")
        if not isinstance(limits, dict):
            limits = _load("service_limits.json")
        if not isinstance(limits, dict) or not limits or limits.get("enforce") is False:
            return None
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_dt()
        rpm = limits.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            ws = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                ts = _parse_dt(r.get("timestamp") or r.get("ts"))
                if ts and ts >= ws:
                    cnt += 1
            if cnt >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rpm, window_seconds=60)
        return None

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        dbs = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not dbs:
            return None, _err("NOT_FOUND", "No Redis databases exist")
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None
        candidates = []
        if isinstance(default_db_id, str) and default_db_id:
            candidates = [d for d in dbs if d.get("id") == default_db_id]
        else:
            flagged = [d for d in dbs if d.get("status") in ("active", "read_only") and (d.get("is_default") is True or d.get("default") is True)]
            if flagged:
                candidates = flagged
            else:
                ar = [d for d in dbs if d.get("status") in ("active", "read_only")]
                if ar:
                    with_num = [d for d in ar if isinstance(d.get("db_number"), int)]
                    candidates = sorted(with_num, key=lambda x: x["db_number"]) if with_num else ar
        if not candidates:
            return None, _err("UNAUTHORIZED", "No configured default database available for this operation")
        db = candidates[0]
        if db.get("status") == "disabled":
            return None, _err("UNAUTHORIZED", "Default Redis database is disabled", db_id=db.get("id"))
        return db, None

    # minimal JSONPath support identical to json_set
    def _parse_path(p):
        if not isinstance(p, str) or not p:
            return None
        if p == "$":
            return []
        if not p.startswith("$"):
            return None
        s = p[1:]
        tokens = []
        i = 0
        while i < len(s):
            if s[i] == ".":
                i += 1
                j = i
                while j < len(s) and s[j] not in ".[":
                    j += 1
                if j == i:
                    return None
                tokens.append(("key", s[i:j]))
                i = j
            elif s[i] == "[":
                j = s.find("]", i)
                if j == -1:
                    return None
                inside = s[i+1:j].strip()
                if inside == "":
                    return None
                try:
                    idx = int(inside)
                except Exception:
                    return None
                tokens.append(("idx", idx))
                i = j + 1
            else:
                return None
        return tokens

    def _get_at(doc, tokens):
        cur = doc
        for t, x in tokens:
            if t == "key":
                if not isinstance(cur, dict) or x not in cur:
                    return None, False
                cur = cur[x]
            else:
                if not isinstance(cur, list):
                    return None, False
                idx = x
                if idx < 0 or idx >= len(cur):
                    return None, False
                cur = cur[idx]
        return cur, True

    if not isinstance(name, str) or not name.strip():
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if path is None:
        path = "$"
    if not isinstance(path, str) or not path:
        _log("error", "VALIDATION_ERROR", {"field": "path"})
        return _err("VALIDATION_ERROR", "path must be a non-empty string", field="path")

    tokens = _parse_path(path)
    if tokens is None:
        _log("error", "VALIDATION_ERROR", {"field": "path"})
        return _err("VALIDATION_ERROR", "Invalid JSON path", field="path")

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", limit_err["error"]["code"])
        return limit_err

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"])
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    vals = _load("redis_values.json")
    if not isinstance(vals, list):
        vals = []
    now = _now_dt()

    key_row = None
    for r in keys:
        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break

    if not key_row or key_row.get("status") != "active":
        _log("success", None, {"key": name, "found": False}, db_id=db_id)
        return {"name": name, "path": path, "value": None}

    exp_dt = _parse_dt(key_row.get("expires_at"))
    if exp_dt and exp_dt <= now:
        key_row["status"] = "expired"
        key_row["updated_at"] = _now_iso()
        _save("redis_keys.json", keys)
        _log("success", None, {"key": name, "found": False, "reason": "expired"}, db_id=db_id)
        return {"name": name, "path": path, "value": None}

    if key_row.get("key_type") != "json":
        _log("error", "VALIDATION_ERROR", {"key": name, "expected": "json", "actual": key_row.get("key_type")}, db_id=db_id)
        return _err("VALIDATION_ERROR", "WRONGTYPE Operation against a key holding the wrong kind of value", key=name, expected_type="json", actual_type=key_row.get("key_type"))

    key_id = key_row.get("id")
    val_row = None
    for v in vals:
        if isinstance(v, dict) and v.get("key_id") == key_id:
            val_row = v
            break

    doc = val_row.get("json_document") if isinstance(val_row, dict) else None
    if doc is None:
        doc = {}

    out, ok = _get_at(doc, tokens)
    if not ok:
        _log("success", None, {"key": name, "found": False, "path": path}, db_id=db_id)
        return {"name": name, "path": path, "value": None}

    key_row["last_accessed_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()
    _save("redis_keys.json", keys)

    _log("success", None, {"key": name, "found": True, "path": path}, db_id=db_id)
    return {"name": name, "path": path, "value": out}

def json_del(name, path="$", **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "json_del"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.replace(tzinfo=None)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        dbs = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not dbs:
            return None, _err("NOT_FOUND", "No Redis databases exist")
        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        candidates = []
        if isinstance(default_db_id, str) and default_db_id:
            candidates = [d for d in dbs if d.get("id") == default_db_id]
        else:
            candidates = [d for d in dbs if d.get("status") in ("active", "read_only")]
            if not candidates:
                candidates = [d for d in dbs if d.get("status") != "disabled"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No usable Redis database available")
        db = candidates[0]
        if db.get("status") == "disabled":
            return None, _err("INVALID_TRANSITION", "Default database is disabled", db_id=db.get("id"))
        return db, None

    def _validate_path(p):
        if p is None:
            return []
        if not isinstance(p, str) or p == "":
            return None
        if p == "$":
            return []
        if not p.startswith("$"):
            return None
        i = 1
        tokens = []
        while i < len(p):
            ch = p[i]
            if ch == ".":
                i += 1
                if i >= len(p):
                    return None
                start = i
                while i < len(p) and p[i] not in ".[":
                    i += 1
                k = p[start:i]
                if not k:
                    return None
                tokens.append(("key", k))
            elif ch == "[":
                i += 1
                if i >= len(p):
                    return None
                start = i
                while i < len(p) and p[i] != "]":
                    i += 1
                if i >= len(p) or p[i] != "]":
                    return None
                idxs = p[start:i].strip()
                i += 1
                try:
                    idx = int(idxs)
                except Exception:
                    return None
                tokens.append(("idx", idx))
            else:
                return None
        return tokens

    if not isinstance(name, str) or not name:
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    tokens = _validate_path(path)
    if tokens is None:
        _log("error", "VALIDATION_ERROR", {"field": "path"})
        return _err("VALIDATION_ERROR", "Invalid JSON path", field="path", path=path)

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], dberr["error"])
        return dberr
    db_id = db.get("id")

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    values_rows = _load("redis_values.json")
    if not isinstance(values_rows, list):
        values_rows = []

    now = _now_dt()

    key_row = None
    for krow in keys:
        if not isinstance(krow, dict):
            continue
        if krow.get("db_id") != db_id or krow.get("key_name") != name:
            continue
        if krow.get("status") != "active":
            continue
        exp = _parse_dt(krow.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        key_row = krow
        break

    if key_row is None:
        _log("ok", None, {"name": name, "deleted": 0}, db_id=db_id)
        return 0

    if key_row.get("key_type") != "json":
        _log("error", "CONFLICT", {"reason": "WRONGTYPE", "expected": "json", "actual": key_row.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="json", actual=key_row.get("key_type"))

    key_id = key_row.get("id")
    vrow = next((v for v in values_rows if isinstance(v, dict) and v.get("key_id") == key_id), None)
    if not vrow:
        _log("ok", None, {"name": name, "deleted": 0}, db_id=db_id)
        return 0
    doc = vrow.get("json_document")
    if doc is None:
        _log("ok", None, {"name": name, "deleted": 0}, db_id=db_id)
        return 0

    def _del_at(root, toks):
        if not toks:
            return None, 1  # delete root
        cur = root
        for i, (tt, tv) in enumerate(toks[:-1]):
            if tt == "key":
                if not isinstance(cur, dict) or tv not in cur:
                    return root, 0
                cur = cur[tv]
            else:
                if not isinstance(cur, list):
                    return root, 0
                idx = tv
                if idx < 0:
                    idx = len(cur) + idx
                if idx < 0 or idx >= len(cur):
                    return root, 0
                cur = cur[idx]
        last_t, last_v = toks[-1]
        if last_t == "key":
            if not isinstance(cur, dict) or last_v not in cur:
                return root, 0
            del cur[last_v]
            return root, 1
        else:
            if not isinstance(cur, list):
                return root, 0
            idx = last_v
            if idx < 0:
                idx = len(cur) + idx
            if idx < 0 or idx >= len(cur):
                return root, 0
            cur.pop(idx)
            return root, 1

    new_doc, deleted = _del_at(doc, tokens)
    if deleted:
        vrow["json_document"] = new_doc
        vrow["updated_at"] = _now_iso()
        key_row["updated_at"] = _now_iso()
        key_row["last_accessed_at"] = _now_iso()
        _save("redis_values.json", values_rows)
        _save("redis_keys.json", keys)

    _log("ok", None, {"name": name, "deleted": deleted, "path": path}, db_id=db_id)
    return deleted

def zrange(key, start, end, with_scores=False, **_extra):
