    def _enforce_limits():
        limits = _load("service_limits.json")
        if not isinstance(limits, dict):
            return None
        rlm = limits.get("rate_limit_per_minute")
        if isinstance(rlm, int) and rlm >= 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            window_start = now - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= window_start:
                        cnt += 1
            if cnt >= rlm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", error_code=limit_err["error"]["code"])
        return limit_err

    if not isinstance(key, str) or key == "":
        e = _err("VALIDATION_ERROR", "key must be a non-empty string")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(start, int) or isinstance(start, bool):
        e = _err("VALIDATION_ERROR", "start must be an integer")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(end, int) or isinstance(end, bool):
        e = _err("VALIDATION_ERROR", "end must be an integer")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(with_scores, bool):
        e = _err("VALIDATION_ERROR", "with_scores must be a boolean")
        _log("error", error_code=e["error"]["code"])
        return e

    settings = _load("redis_settings.json")
    default_db_id = settings.get("default_db_id") if isinstance(settings, dict) else None
    dbs = _load("redis_databases.json")
    if not isinstance(dbs, list):
        dbs = []
    if not default_db_id:
        active_dbs = [d for d in dbs if isinstance(d, dict) and d.get("status") in ("active", "read_only")]
        if len(active_dbs) == 1:
            default_db_id = active_dbs[0].get("id")
        else:
            e = _err("UNAUTHORIZED", "No configured default database")
            _log("error", error_code=e["error"]["code"])
            return e
    db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == default_db_id), None)
    if not db:
        e = _err("NOT_FOUND", "Default database not found")
        _log("error", error_code=e["error"]["code"])
        return e
    if db.get("status") == "disabled":
        e = _err("UNAUTHORIZED", "Default database is disabled")
        _log("error", error_code=e["error"]["code"])
        return e

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []

    # opportunistically expire
    changed_exp = False
    for kr in keys:
        if not isinstance(kr, dict):
            continue
        if kr.get("db_id") != default_db_id or kr.get("status") != "active":
            continue
        exp = kr.get("expires_at")
        if isinstance(exp, str):
            try:
                exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")).replace(tzinfo=None)
                if exp_dt <= now:
                    kr["status"] = "expired"
                    kr["updated_at"] = now_iso
                    changed_exp = True
            except Exception:
                pass
    if changed_exp:
        _save("redis_keys.json", keys)

    key_row = next((kr for kr in keys if isinstance(kr, dict) and kr.get("db_id") == default_db_id and kr.get("key_name") == key), None)
    # missing behaves like empty array for reads? Tool description says "or an error message".
    # Redis ZRANGE on missing key returns empty list; WRONGTYPE on wrong type.
    if not key_row or key_row.get("status") != "active":
        _log("success")
        return {"key": key, "members": [], "with_scores": with_scores, "message": "OK"}

    exp = key_row.get("expires_at")
    if isinstance(exp, str):
        try:
            exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")).replace(tzinfo=None)
            if exp_dt <= now:
                _log("success")
                return {"key": key, "members": [], "with_scores": with_scores, "message": "OK"}
        except Exception:
            pass

    if key_row.get("key_type") != "zset":
        e = _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value")
        _log("error", error_code=e["error"]["code"])
        return e

    values = _load("redis_values.json")
    if not isinstance(values, list):
        values = []
    value_row = next((vr for vr in values if isinstance(vr, dict) and vr.get("key_id") == key_row.get("id")), None)
    z = []
    if value_row and isinstance(value_row.get("zset_value"), list):
        z = [el for el in value_row["zset_value"] if isinstance(el, dict) and isinstance(el.get("member"), str) and (isinstance(el.get("score"), int) or isinstance(el.get("score"), float))]

    # sort by score then member
    z_sorted = sorted(z, key=lambda x: (float(x["score"]), x["member"]))

    n = len(z_sorted)
    def _norm_index(i):
        return i + n if i < 0 else i

    s = _norm_index(start)
    eidx = _norm_index(end)

    if n == 0:
        key_row["last_accessed_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("redis_keys.json", keys)
        _log("success")
        return {"key": key, "members": [], "with_scores": with_scores, "message": "OK"}

    if s < 0:
        s = 0
    if eidx < 0:
        # if end is very negative after normalization, return empty
        key_row["last_accessed_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("redis_keys.json", keys)
        _log("success")
        return {"key": key, "members": [], "with_scores": with_scores, "message": "OK"}
    if s >= n:
        key_row["last_accessed_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("redis_keys.json", keys)
        _log("success")
        return {"key": key, "members": [], "with_scores": with_scores, "message": "OK"}
    if eidx >= n:
        eidx = n - 1
    if eidx < s:
        key_row["last_accessed_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("redis_keys.json", keys)
        _log("success")
        return {"key": key, "members": [], "with_scores": with_scores, "message": "OK"}

    slice_ = z_sorted[s:eidx + 1]
    if with_scores:
        out = [{"member": el["member"], "score": float(el["score"])} for el in slice_]
    else:
        out = [el["member"] for el in slice_]

    key_row["last_accessed_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("redis_keys.json", keys)

    _log("success")
    return {"key": key, "members": out, "with_scores": with_scores, "message": "OK"}

