            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(name, str) or not name:
        return _err("VALIDATION_ERROR", "name must be a non-empty string")

    t0 = datetime.datetime.utcnow()
    now = t0.replace(microsecond=0).isoformat() + "Z"

    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if d.get("status") in ("active", "read_only"):
            default_db = d
            break
    if not default_db:
        return _err("UNAUTHORIZED", "No active default Redis database is available")
    if default_db.get("status") == "disabled":
        return _err("UNAUTHORIZED", "Default Redis database is disabled")
    db_id = default_db.get("id")

    keys = _load("redis_keys.json")
    vals = _load("redis_values.json")

    key_row = None
    for r in keys:
        if r.get("db_id") == db_id and r.get("key_name") == name:
            key_row = r
            break

    if not key_row or key_row.get("status") != "active":
        return {"name": name, "members": [], "db_id": db_id}

    expires_at = key_row.get("expires_at")
    if isinstance(expires_at, str) and expires_at:
        try:
            exp_dt = datetime.datetime.fromisoformat(expires_at.replace("Z", "+00:00"))
            if exp_dt <= datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc):
                # Mark expired and behave as missing
                key_row["status"] = "expired"
                key_row["updated_at"] = now
                _save("redis_keys.json", keys)
                return {"name": name, "members": [], "db_id": db_id}
        except ValueError:
            return _err("CONFLICT", "Stored expires_at is invalid ISO datetime", field="expires_at", value=expires_at)

    if key_row.get("key_type") != "set":
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="set", actual=key_row.get("key_type"))

    key_id = key_row.get("id")
    val_row = None
    for v in vals:
        if v.get("key_id") == key_id:
            val_row = v
            break
    if not val_row:
        return _err("CONFLICT", "Value record missing for set key")

    set_value = val_row.get("set_value")
    if set_value is None:
        set_value = []
    if not isinstance(set_value, list):
        return _err("CONFLICT", "Stored set_value is invalid", field="set_value")

    # Read updates last_accessed_at
    key_row["last_accessed_at"] = now
    key_row["updated_at"] = now
    _save("redis_keys.json", keys)

    # Enforce uniqueness in returned data (sets are unique)
    seen = set()
    members = []
    for m in set_value:
        if isinstance(m, str) and m not in seen:
            seen.add(m)
            members.append(m)

    return {"name": name, "members": members, "db_id": db_id}

def xadd(key, fields, expiration=None, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(key, str) or not key:
        return _err("VALIDATION_ERROR", "key must be a non-empty string")
    if not isinstance(fields, dict):
        return _err("VALIDATION_ERROR", "fields must be an object/dict")
    if expiration is not None:
        if not isinstance(expiration, int):
            return _err("VALIDATION_ERROR", "expiration must be an integer")
        if expiration < 1:
            return _err("VALIDATION_ERROR", "expiration must be >= 1")

    t0 = datetime.datetime.utcnow()
    now_dt = t0.replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if d.get("status") in ("active", "read_only"):
            default_db = d
            break
    if not default_db:
        return _err("UNAUTHORIZED", "No active default Redis database is available")
    if default_db.get("status") == "disabled":
        return _err("UNAUTHORIZED", "Default Redis database is disabled")
    db_id = default_db.get("id")

    keys = _load("redis_keys.json")
    vals = _load("redis_values.json")

    # Find existing key
    key_row = None
    for r in keys:
        if r.get("db_id") == db_id and r.get("key_name") == key:
            key_row = r
            break

    # If exists but not active, treat as not found for upsert? We'll upsert by reactivating only if deleted/expired is not allowed by lifecycle.
    # Lifecycle: active -> expired/deleted; expired -> deleted; deleted -> []
    # So we must create a new key row instead of reactivating deleted/expired.
    def _gen_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    if key_row and key_row.get("status") == "active":
        # check expiration
        expires_at = key_row.get("expires_at")
        if isinstance(expires_at, str) and expires_at:
            try:
                exp_dt = datetime.datetime.fromisoformat(expires_at.replace("Z", "+00:00"))
                if exp_dt <= datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc):
                    key_row["status"] = "expired"
                    key_row["updated_at"] = now
                    _save("redis_keys.json", keys)
                    key_row = None
            except ValueError:
                return _err("CONFLICT", "Stored expires_at is invalid ISO datetime", field="expires_at", value=expires_at)

    if key_row:
        if key_row.get("key_type") != "stream":
            return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="stream", actual=key_row.get("key_type"))
        key_id = key_row.get("id")
    else:
        # create new stream key
        key_id = _gen_id("rkey")
        new_key = {
            "id": key_id,
            "db_id": db_id,
            "key_name": key,
            "key_type": "stream",
            "encoding": None,
            "ttl_seconds": None,
            "expires_at": None,
            "status": "active",
            "approx_size_bytes": None,
            "last_accessed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        # Uniqueness (db_id, key_name) among all keys: enforce active uniqueness at least; schema says unique(db_id,key_name)
        for r in keys:
            if r.get("db_id") == db_id and r.get("key_name") == key:
                return _err("CONFLICT", "Key name already exists in db", name=key)
        keys.append(new_key)
        key_row = new_key

    # Apply expiration
    if expiration is not None:
        key_row["ttl_seconds"] = expiration
        exp_dt = now_dt + datetime.timedelta(seconds=expiration)
        key_row["expires_at"] = exp_dt.isoformat() + "Z"
    else:
        # do not change TTL on XADD? Vendor rule says "expiration if provided ... stores as appended object"; leave as-is if already set? Redis doesn't change TTL unless explicit.
        # We'll implement: only set if provided; otherwise leave existing fields untouched.
        pass

    key_row["last_accessed_at"] = now
    key_row["updated_at"] = now

    # Ensure value row exists with only stream_value non-null
    val_row = None
    for v in vals:
        if v.get("key_id") == key_id:
            val_row = v
            break

    if not val_row:
        val_row = {
            "id": _gen_id("rval"),
            "key_id": key_id,
            "db_id": db_id,
            "string_value": None,
            "hash_value": None,
            "list_value": None,
            "set_value": None,
            "zset_value": None,
            "stream_value": [],
            "json_document": None,
            "created_at": now,
            "updated_at": now,
        }
        vals.append(val_row)

    # Validate shape: stream_value list
    if val_row.get("db_id") != db_id:
        return _err("CONFLICT", "Value row db_id does not match key db_id")
    stream_value = val_row.get("stream_value")
    if stream_value is None:
        stream_value = []
    if not isinstance(stream_value, list):
        return _err("CONFLICT", "Stored stream_value is invalid", field="stream_value")

    # Generate entry_id like Redis: <msTime>-<seq>
    ms = int(datetime.datetime.utcnow().timestamp() * 1000)
    # sequence: count existing entries with same ms
    seq = 0
    for e in stream_value:
        if isinstance(e, dict) and isinstance(e.get("entry_id"), str):
            eid = e.get("entry_id")
            if eid.startswith(str(ms) + "-"):
                try:
                    s = int(eid.split("-", 1)[1])
                    if s >= seq:
                        seq = s + 1
                except Exception:
                    continue
    entry_id = f"{ms}-{seq}"

    entry = {"entry_id": entry_id, "fields": fields, "created_at": now}
    stream_value.append(entry)
    val_row["stream_value"] = stream_value
    val_row["updated_at"] = now

    _save("redis_keys.json", keys)
    _save("redis_values.json", vals)

    return {"key": key, "entry_id": entry_id, "db_id": db_id}

def xrange(key, count=1, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(key, str) or not key:
        return _err("VALIDATION_ERROR", "key must be a non-empty string")
    if count is None:
        count = 1
    if not isinstance(count, int):
        return _err("VALIDATION_ERROR", "count must be an integer")
    if count < 1 or count > 10000:
        return _err("VALIDATION_ERROR", "count must be between 1 and 10000")

    t0 = datetime.datetime.utcnow()
    now = t0.replace(microsecond=0).isoformat() + "Z"

    dbs = _load("redis_databases.json")
    default_db = None
    for d in dbs:
        if d.get("status") in ("active", "read_only"):
            default_db = d
            break
    if not default_db:
        return _err("UNAUTHORIZED", "No active default Redis database is available")
    if default_db.get("status") == "disabled":
        return _err("UNAUTHORIZED", "Default Redis database is disabled")
    db_id = default_db.get("id")

    keys = _load("redis_keys.json")
    vals = _load("redis_values.json")

    key_row = None
    for r in keys:
        if r.get("db_id") == db_id and r.get("key_name") == key:
            key_row = r
            break

    if not key_row or key_row.get("status") != "active":
        return {"key": key, "entries": [], "db_id": db_id}

    expires_at = key_row.get("expires_at")
    if isinstance(expires_at, str) and expires_at:
        try:
            exp_dt = datetime.datetime.fromisoformat(expires_at.replace("Z", "+00:00"))
            if exp_dt <= datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc):
                key_row["status"] = "expired"
                key_row["updated_at"] = now
                _save("redis_keys.json", keys)
                return {"key": key, "entries": [], "db_id": db_id}
        except ValueError:
            return _err("CONFLICT", "Stored expires_at is invalid ISO datetime", field="expires_at", value=expires_at)

    if key_row.get("key_type") != "stream":
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="stream", actual=key_row.get("key_type"))

    key_id = key_row.get("id")
    val_row = None
    for v in vals:
        if v.get("key_id") == key_id:
            val_row = v
            break
    if not val_row:
        return _err("CONFLICT", "Value record missing for stream key")

    stream_value = val_row.get("stream_value")
    if stream_value is None:
        stream_value = []
    if not isinstance(stream_value, list):
        return _err("CONFLICT", "Stored stream_value is invalid", field="stream_value")

    # Implementation choice: return earliest entries (left to right) up to count.
    entries = stream_value[:count]

    key_row["last_accessed_at"] = now
    key_row["updated_at"] = now
    _save("redis_keys.json", keys)

    return {"key": key, "entries": entries, "count": len(entries), "db_id": db_id}

