        if isinstance(r, dict) and r.get("db_id") == db_id and r.get("key_name") == key:
            key_row = r
            break

    if key_row is None or not _is_active_not_expired(key_row):
        _log("error", "NOT_FOUND", {"key": key}, db_id=db_id)
        return _err("NOT_FOUND", "Key not found", key=key)

    if key_row.get("key_type") != "stream":
        _log("error", "CONFLICT", {"rule": "WRONGTYPE", "expected": "stream", "found": key_row.get("key_type")}, db_id=db_id)
        return _err("CONFLICT", "WRONGTYPE Operation against a key holding the wrong kind of value", expected="stream", found=key_row.get("key_type"))

    vrow = None
    for v in values:
        if isinstance(v, dict) and v.get("key_id") == key_row.get("id"):
            vrow = v
            break
    stream = vrow.get("stream_value") if isinstance(vrow, dict) else None
    if not isinstance(stream, list):
        stream = []

    before = len(stream)
    stream2 = []
    deleted = 0
    for e in stream:
        if isinstance(e, dict) and e.get("entry_id") == entry_id:
            deleted = 1
            continue
        stream2.append(e)

    if deleted == 0:
        # Redis XDEL returns 0 when nothing deleted; not an error.
        _log("ok", None, {"key": key, "entry_id": entry_id, "deleted": 0}, db_id=db_id)
        return {"key": key, "entry_id": entry_id, "deleted": 0}

    # persist update
    if vrow is None:
        # stream key exists but missing value row -> cannot delete anything (shouldn't happen due to deleted==1)
        _log("error", "CONFLICT", {"rule": "missing_value_row"}, db_id=db_id)
        return _err("CONFLICT", "Stream value missing for key", key=key)

    vrow["stream_value"] = stream2
    vrow["updated_at"] = _now_iso()
    key_row["updated_at"] = _now_iso()
    _save("redis_values.json", values)
    _save("redis_keys.json", keys)

    _log("ok", None, {"key": key, "entry_id": entry_id, "deleted": 1, "before": before, "after": len(stream2)}, db_id=db_id)
    return {"key": key, "entry_id": entry_id, "deleted": 1}

def publish(channel, message, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "publish"
    t0 = datetime.datetime.utcnow()

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _log(status, error_code=None, meta=None, db_id=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "db_id": db_id,
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        dbs = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not dbs:
            return None, _err("NOT_FOUND", "No Redis databases exist")

        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        candidates = []
        if isinstance(default_db_id, str) and default_db_id:
            candidates = [d for d in dbs if d.get("id") == default_db_id]
        else:
            candidates = [d for d in dbs if d.get("status") in ("active", "read_only")]
            if not candidates:
                candidates = [d for d in dbs if d.get("status") != "disabled"]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No usable Redis database available")
        db = candidates[0]
        if db.get("status") == "disabled":
            return None, _err("INVALID_TRANSITION", "Default database is disabled", db_id=db.get("id"))
        return db, None

    # Validate
    if not isinstance(channel, str) or not channel:
        _log("error", "VALIDATION_ERROR", {"field": "channel"})
        return _err("VALIDATION_ERROR", "channel must be a non-empty string", field="channel")
    if not isinstance(message, str):
        _log("error", "VALIDATION_ERROR", {"field": "message"})
        return _err("VALIDATION_ERROR", "message must be a string", field="message")

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], dberr["error"])
        return dberr
    db_id = db.get("id")

    sessions = _load("redis_runtime_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    subscribers = 0
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("db_id") != db_id:
            continue
        if s.get("session_type") != "pubsub_subscription":
            continue
        if s.get("status") != "active":
            continue
        if s.get("channel") == channel:
            subscribers += 1

    _log("ok", None, {"channel": channel, "subscribers": subscribers}, db_id=db_id)
    return {"channel": channel, "subscribers": subscribers}

