        for d in dbs:
            if isinstance(d, dict) and d.get("status") in ("active", "read_only"):
                return d, None

        for d in dbs:
            if isinstance(d, dict) and d.get("status") == "disabled":
                return None, _err("UNAUTHORIZED", "Default database is disabled", db_id=d.get("id"))
        return None, _err("UNAUTHORIZED", "No available default database")

    if not isinstance(channel, str) or not channel:
        _log("error", "VALIDATION_ERROR", {"field": "channel"})
        return _err("VALIDATION_ERROR", "channel must be a non-empty string", field="channel")

    limerr = _enforce_limits()
    if limerr:
        _log("error", limerr["error"]["code"], {"op": "limit"})
        return limerr

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"], {"op": "resolve_default_db"})
        return dberr
    db_id = db.get("id")

    sessions = _load("redis_runtime_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # De-duplicate: if an active subscription exists for this channel (client_id is null in this simplified API), return it.
    existing = None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("db_id") == db_id and s.get("session_type") == "pubsub_subscription" and s.get("status") == "active" and s.get("channel") == channel and s.get("client_id") in (None, ""):
            existing = s
            break

    if existing is not None:
        existing["last_heartbeat_at"] = _now_iso()
        existing["updated_at"] = _now_iso()
        _save("redis_runtime_sessions.json", sessions)
        _log("ok", None, {"channel": channel, "deduped": True}, db_id=db_id)
        return {"status": "success", "channel": channel, "subscribed": True, "session_id": existing.get("id")}

    row = {
        "id": "rsess_" + uuid.uuid4().hex[:26],
        "db_id": db_id,
        "session_type": "pubsub_subscription",
        "client_id": None,
        "client_addr": None,
        "client_name": None,
        "channel": channel,
        "status": "active",
        "last_heartbeat_at": _now_iso(),
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    sessions.append(row)
    _save("redis_runtime_sessions.json", sessions)
    _log("ok", None, {"channel": channel, "created": True}, db_id=db_id)
    return {"status": "success", "channel": channel, "subscribed": True, "session_id": row["id"]}

