def get_databases(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_databases"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None, meta=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    # Validate
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "read_only", "disabled"):
            _log("error", "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status filter", field="status")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("error", "VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        _log("error", "VALIDATION_ERROR", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")

    dbs = _load("redis_databases.json")
    if not isinstance(dbs, list):
        dbs = []
    rows = [d for d in dbs if isinstance(d, dict)]

    # Sort by db_number then id for stable paging
    def _sort_key(r):
        n = r.get("db_number")
        n2 = n if isinstance(n, int) else 10**9
        return (n2, str(r.get("id") or ""))
    rows.sort(key=_sort_key)

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    start = 0
    if cursor is not None:
        # Cursor is the last seen id; if unknown, start from beginning (do not error)
        idx = None
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            start = idx + 1
        else:
            start = 0

    page = rows[start:start + limit]
    next_cursor = None
    if start + limit < len(rows) and page:
        next_cursor = page[-1].get("id")

    _log("ok", None, {"returned": len(page), "total": len(rows), "next_cursor": next_cursor})
    return {
        "data": page,
        "limit": limit,
        "total": len(rows),
        "has_more": bool(next_cursor),
        "next_cursor": next_cursor,
    }

def get_database(db_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("redis_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    limit_per_window = 240
    cutoff = time.time() - window_s
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff and r.get("endpoint") == "get_database":
                    recent += 1
            except Exception:
                pass
    if recent >= limit_per_window:
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "get_database",
            "status": "RATE_LIMIT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    if not isinstance(db_id, str) or not re.match(r"^rdb_[0-9A-HJKMNP-TV-Z]{10,}$", db_id):
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "get_database",
            "status": "VALIDATION_ERROR",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "db_id is missing or malformed")

    dbs = _load("redis_databases.json")
    if not isinstance(dbs, list):
        dbs = []

    found = None
    for d in dbs:
        if isinstance(d, dict) and d.get("id") == db_id:
            found = d
            break

    if not found:
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "get_database",
            "status": "NOT_FOUND",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("NOT_FOUND", "Database not found")

    log_row = {
        "id": "rlog_" + str(int(time.time() * 1000)),
        "endpoint": "get_database",
        "status": "OK",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    logs.append(log_row)
    _save("redis_request_logs.json", logs)
    return {"database": found}

