    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    logs = _load("redis_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_s = 60
    limit_per_window = 60
    cutoff = time.time() - window_s
    recent = 0
    for r in logs:
        ts = r.get("timestamp")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff and r.get("endpoint") == "update_database":
                    recent += 1
            except Exception:
                pass
    if recent >= limit_per_window:
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "update_database",
            "status": "RATE_LIMIT",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    if not isinstance(db_id, str) or not re.match(r"^rdb_[0-9A-HJKMNP-TV-Z]{10,}$", db_id):
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "update_database",
            "status": "VALIDATION_ERROR",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "db_id is missing or malformed")

    if name is not None:
        if (not isinstance(name, str)) or len(name) < 1 or len(name) > 128:
            log_row = {
                "id": "rlog_" + str(int(time.time() * 1000)),
                "endpoint": "update_database",
                "status": "VALIDATION_ERROR",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(log_row)
            _save("redis_request_logs.json", logs)
            return _err("VALIDATION_ERROR", "name must be a string of length 1..128")
        if name.strip() == "":
            log_row = {
                "id": "rlog_" + str(int(time.time() * 1000)),
                "endpoint": "update_database",
                "status": "VALIDATION_ERROR",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(log_row)
            _save("redis_request_logs.json", logs)
            return _err("VALIDATION_ERROR", "name must not be empty")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "read_only", "disabled"):
            log_row = {
                "id": "rlog_" + str(int(time.time() * 1000)),
                "endpoint": "update_database",
                "status": "VALIDATION_ERROR",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(log_row)
            _save("redis_request_logs.json", logs)
            return _err("VALIDATION_ERROR", "Invalid status")

    if config is not None and not isinstance(config, dict):
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "update_database",
            "status": "VALIDATION_ERROR",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "config must be an object")

    dbs = _load("redis_databases.json")
    if not isinstance(dbs, list):
        dbs = []

    idx = None
    for i, d in enumerate(dbs):
        if isinstance(d, dict) and d.get("id") == db_id:
            idx = i
            break
    if idx is None:
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "update_database",
            "status": "NOT_FOUND",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("NOT_FOUND", "Database not found")

    cur = dbs[idx]
    if not isinstance(cur, dict):
        log_row = {
            "id": "rlog_" + str(int(time.time() * 1000)),
            "endpoint": "update_database",
            "status": "NOT_FOUND",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(log_row)
        _save("redis_request_logs.json", logs)
        return _err("NOT_FOUND", "Database not found")

    # uniqueness of db_number (constraint)
    # db_number not mutable here, but ensure datastore integrity if it would be violated by concurrent bad data.
    db_number = cur.get("db_number")
    if isinstance(db_number, int):
        seen = 0
        for d in dbs:
            if isinstance(d, dict) and d.get("db_number") == db_number:
                seen += 1
        if seen > 1:
            log_row = {
                "id": "rlog_" + str(int(time.time() * 1000)),
                "endpoint": "update_database",
                "status": "CONFLICT",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(log_row)
            _save("redis_request_logs.json", logs)
            return _err("CONFLICT", "Datastore violates unique(db_number) constraint")

    # status transition validation per lifecycle
    transitions = {
        "active": ("read_only", "disabled"),
        "read_only": ("active", "disabled"),
        "disabled": ("active",),
    }
    new_row = copy.deepcopy(cur)
    if status is not None and status != cur.get("status"):
        from_status = cur.get("status")
        if from_status not in transitions or status not in transitions[from_status]:
            log_row = {
                "id": "rlog_" + str(int(time.time() * 1000)),
                "endpoint": "update_database",
                "status": "INVALID_TRANSITION",
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            logs.append(log_row)
            _save("redis_request_logs.json", logs)
            return _err("INVALID_TRANSITION", f"Invalid status transition {from_status} -> {status}")
        new_row["status"] = status

    if name is not None:
        new_row["name"] = name
    if config is not None:
        new_row["config"] = config

    new_row["updated_at"] = now
    dbs[idx] = new_row
    _save("redis_databases.json", dbs)

    log_row = {
        "id": "rlog_" + str(int(time.time() * 1000)),
        "endpoint": "update_database",
        "status": "OK",
        "timestamp": now,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    logs.append(log_row)
    _save("redis_request_logs.json", logs)

    return {"database": new_row}

def get_key(key, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0533000" if __import__("os").path.isdir("./environment_mix/0533000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_key"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, error_code=None, meta=None):
        logs = _load("redis_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("redis_request_logs.json", logs)

    def _resolve_default_db():
        dbs = _load("redis_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        db_rows = [d for d in dbs if isinstance(d, dict) and isinstance(d.get("id"), str)]
        if not db_rows:
            return None, _err("NOT_FOUND", "No Redis databases exist")

        cfg = _load("redis_service_config.json")
        default_db_id = cfg.get("default_db_id") if isinstance(cfg, dict) else None

        if isinstance(default_db_id, str) and default_db_id:
            db = next((d for d in db_rows if d.get("id") == default_db_id), None)
            if not db:
                return None, _err("NOT_FOUND", "Configured default database not found", default_db_id=default_db_id)
            if db.get("status") == "disabled":
                return None, _err("INVALID_TRANSITION", "Default database is disabled", db_id=db.get("id"))
            return db, None

        usable = [d for d in db_rows if d.get("status") in ("active", "read_only")]
        if not usable:
            return None, _err("UNAUTHORIZED", "No usable default database available")
        usable_with_num = [d for d in usable if isinstance(d.get("db_number"), int)]
        if usable_with_num:
            return sorted(usable_with_num, key=lambda x: x["db_number"])[0], None
        return usable[0], None

    if not isinstance(key, str) or not key.strip():
        _log("error", "VALIDATION_ERROR", {"field": "key"})
        return _err("VALIDATION_ERROR", "key is missing or invalid", field="key")

    db, dberr = _resolve_default_db()
    if dberr:
        _log("error", dberr["error"]["code"])
        return dberr
    db_id = db["id"]

    keys = _load("redis_keys.json")
    if not isinstance(keys, list):
        keys = []
    now = _now_dt()

    krow = None
    for r in keys:
        if not isinstance(r, dict):
            continue
        if r.get("db_id") != db_id:
            continue
        if r.get("key_name") != key:
            continue
        if r.get("status") != "active":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        krow = r
        break

    if not krow:
        _log("error", "NOT_FOUND", {"db_id": db_id, "key": key})
        return _err("NOT_FOUND", "Key not found", key=key)

    _log("ok", None, {"db_id": db_id, "key": key, "key_id": krow.get("id")})
    return krow

